import type { AuthoredQuiz } from '../../advanced/shared/authoredQuiz';

// Fifteen authored questions per proficiency writing lesson (key = lesson id).
export const proficiencyWritingQuizBank: Record<number, AuthoredQuiz[]> = {
  1: [
    ["In the model text for the C2 diagnostic essay, the central claim should be exact rather than merely what?","Forceful",["Original","Concise","Personal"],"Teks model menegaskan bahwa klaim utama harus tepat (exact), bukan sekadar tegas atau 'forceful'."],
    ["The writing task asks for an essay on language learning and professional identity. Which element is NOT one of its stated requirements?","An anecdote opening the first paragraph",["A precise and defensible thesis statement","One concession acknowledging another view","A conclusion that synthesises the argument"],"Tugas menulis meminta tesis tepat, dua bagian, satu konsesi, kualifikasi, dan kesimpulan sintesis, tetapi tidak mewajibkan anekdot pembuka."],
    ["Which thesis best suits a diagnostic essay on language learning and professional identity?","Fluency in English often reshapes professional identity, less through the skill itself than through the networks it opens.",["Learning English is extremely important for every professional who wants to succeed and be respected in today's globalised world.","This essay will examine several ways in which language learning may be connected to professional identity in the modern workplace.","Language learning and professional identity are both complex topics on which many experts continue to hold very different opinions."],"Tesis ini membuat klaim yang spesifik dan terkualifikasi tentang mekanisme hubungan antara kefasihan bahasa dan identitas profesional."],
    ["Prompt: 'To what extent should museums return artefacts acquired during colonial rule?' Which opening claim best answers the phrase 'to what extent'?","Restitution is justified in most cases of coercive acquisition, but the obligation weakens where provenance is genuinely contested.",["Museums around the world contain many thousands of artefacts that were acquired during the long and often violent colonial period of history.","Museums should return every artefact immediately, since keeping any of them is morally indefensible in all circumstances.","There are many arguments on both sides of this debate, and this essay will discuss each of them carefully in turn."],"Frasa 'to what extent' menuntut penilaian derajat, dan kalimat ini menyatakan sejauh mana klaim berlaku beserta batasnya."],
    ["Spot the main weakness in this diagnostic-essay opening: 'Since the dawn of time, humanity has always argued about whether art should be useful.'","It opens with a sweeping, unverifiable cliché instead of a focused claim.",["It uses the present perfect where the simple past is strictly required here.","It is too informal because it relies on the everyday verb 'argued'.","It states the thesis too early, before any context has been given."],"Pembukaan 'since the dawn of time' adalah klise umum yang tidak dapat diverifikasi dan tidak memberi klaim yang terfokus."],
    ["You have 60 minutes for a C2 diagnostic essay. Which use of the first eight minutes is most effective?","Decoding the prompt, fixing a position, and sketching paragraph functions",["Writing a polished introduction before deciding on the argument as a whole","Listing advanced vocabulary to insert wherever it might fit","Drafting the conclusion first so that the ending is memorable"],"Perencanaan awal yang memahami soal, menetapkan posisi, dan memetakan fungsi paragraf menghasilkan esai yang terkendali."],
    ["Which sentence shows the most appropriate register for a C2 diagnostic essay on urban noise?","Persistent exposure to traffic noise imposes costs that are rarely visible in planning decisions.",["Traffic noise is a real pain, and city planners just don't seem to get it at all.","It is my humble opinion that noise is a thing which is quite bad for people's health.","Noise, that most insidious of urban phantoms, haunts our every waking hour without any mercy at all."],"Kalimat ini formal, tepat, dan tidak berlebihan, sesuai register esai akademik C2."],
    ["Which is the best concise revision of 'In my personal opinion, I think that it is possibly the case that tourism may harm fragile ecosystems'?","Tourism may harm fragile ecosystems.",["Tourism harms ecosystems.","I think tourism possibly may harm fragile ecosystems.","It is possibly the case that tourism harms ecosystems."],"Revisi ini menghapus pengulangan opini dan hedging ganda sambil mempertahankan makna serta tingkat kehati-hatian klaim."],
    ["Evidence: two small surveys suggest that bilingual employees negotiate salaries more confidently. Which claim is calibrated appropriately?","Limited survey evidence suggests that bilingualism may be associated with greater confidence in salary negotiation.",["Bilingualism makes employees far more confident whenever they sit down to negotiate their salaries with their employers.","Research has now proven beyond doubt that bilingual employees always negotiate better salaries than monolinguals.","It is completely impossible to say anything meaningful about bilingualism and salary negotiation at this point."],"Klaim ini sebanding dengan bukti yang terbatas: menyebut sumbernya dan memakai hedging 'suggests' serta 'may be associated'."],
    ["Which concession best strengthens an argument that standardised testing should be reduced?","Standardised tests do offer comparability across schools, yet this advantage is bought at the cost of a narrowed curriculum.",["Some people like standardised tests, but they are simply wrong and their views should not be taken seriously at all.","Standardised tests are completely useless in every respect, although a few teachers may perhaps disagree with this particular view.","Admittedly, standardised tests exist in a great many countries, which clearly shows that they are now very widespread."],"Konsesi yang kuat mengakui keunggulan nyata pihak lawan lalu menunjukkan mengapa argumen penulis tetap lebih kuat."],
    ["Which final sentence best concludes a diagnostic essay arguing that public libraries remain essential?","Libraries endure not as warehouses of books but as one of the few civic spaces that ask nothing of their users.",["In conclusion, libraries are essential, as I have said several times throughout the course of this essay.","Libraries also offer free computer classes, which is yet another good reason why councils should fund them.","Therefore, everyone in the country should make an effort to visit a library at least once every single week of the year."],"Kalimat ini menyintesis argumen dan mempertajam implikasinya, bukan sekadar mengulang atau menambah poin baru."],
    ["Which sentence best fills the gap? 'Online reviews shape consumer choice. ___ Many reviews are written by people paid to write them.'","That influence, however, rests on an assumption of authenticity that is increasingly hard to sustain.",["Furthermore, there are many different websites where reviews of all kinds of products and services can be found.","In addition, most consumers enjoy reading a few reviews before they decide to buy something new.","As a result, companies are now always honest about the products and services that they sell."],"Kalimat ini merujuk balik ('That influence') dan menyiapkan kontras dengan kalimat berikutnya sehingga kohesinya logis."],
    ["Choose the most precise word: 'The reform did not abolish the exam; it merely ___ its weight in final grades.'","attenuated",["annihilated","accentuated","amplified"],"'Attenuated' berarti mengurangi kekuatan atau bobot, sesuai dengan kontras 'did not abolish ... merely'."],
    ["A marker notes that a diagnostic essay 'displays range but not control'. Which revision priority follows most directly?","Replacing showy but imprecise vocabulary with exact, well-collocated choices",["Adding more idioms and rare words to every paragraph of the essay","Lengthening sentences so that each one includes several more subordinate clauses","Removing all complex structures in favour of short, simple sentences"],"Komentar 'range but not control' berarti kosakata beragam tetapi kurang tepat, sehingga yang perlu diperbaiki adalah ketepatan."],
    ["In the lesson's paragraph architecture (claim, evidence, analysis, ...), which element follows analysis?","Qualification",["Evidence","Recommendation","Restatement"],"Arsitektur paragraf dalam pelajaran ini adalah klaim, bukti, analisis, kualifikasi, lalu tautan (link)."],
  ],
  2: [
    ["The model text says a stronger text 'moves beyond assertion'. Which sequence does it then describe?","Define the problem, qualify the claim, acknowledge an objection, defend the interpretation",["State the claim, repeat it, add several examples, and then restate it more forcefully","Summarise the sources, list the main opinions, and let the reader decide everything for themselves","Narrate a personal experience, describe the feelings involved, and draw a clear moral"],"Teks model menjelaskan bahwa teks yang kuat mendefinisikan masalah, membatasi klaim, mengakui keberatan, lalu mempertahankan interpretasinya."],
    ["Which thesis best suits an academic argument on public trust in expert knowledge?","Public trust in expertise has not collapsed so much as fragmented, attaching to individual experts rather than to institutions.",["Nobody trusts experts any more, and this is a complete disaster for modern democratic societies everywhere in the world.","Experts are very important people whose specialised knowledge should always be trusted by the general public without any question.","This essay discusses the topic of public trust in experts from a number of different and sometimes conflicting points of view."],"Tesis ini membuat klaim yang tajam dan dapat diperdebatkan dengan membedakan 'runtuh' dan 'terfragmentasi'."],
    ["Which phrase does the lesson list as a tool for qualification?","This does not necessarily imply",["Taken together, these considerations suggest","More specifically, in practical terms","The stronger interpretation is"],"Dalam daftar language tools, 'this does not necessarily imply' termasuk alat kualifikasi, sedangkan yang lain untuk presisi atau sintesis."],
    ["Choose the reporting verb that signals the writer accepts the source's claim: 'Okafor (2019) ___ that rural literacy gains were driven by radio programmes.'","demonstrates",["claims","alleges","hypothesises"],"'Demonstrates' menunjukkan penulis menerima klaim sebagai terbukti, sedangkan 'claims', 'alleges', dan 'speculates' menjaga jarak."],
    ["Argument: 'Citizens who distrust vaccines distrust science; therefore, more science education will restore trust.' What is the unstated assumption?","That distrust stems from a lack of knowledge rather than from doubts about institutions",["That science education is already compulsory in most secondary schools across the country","That vaccines are the only scientific topic that citizens care about","That trust in science has increased steadily over recent decades"],"Argumen ini mengandaikan ketidakpercayaan disebabkan kurangnya pengetahuan, padahal bisa jadi bersumber dari ketidakpercayaan pada institusi."],
    ["Spot the logical weakness: 'Since the professor is a Nobel laureate in physics, her views on monetary policy must be correct.'","It appeals to authority outside the expert's field",["It relies on a false dilemma between two options","It attacks the character of an opponent instead","It generalises from a single unrepresentative case"],"Keahlian di bidang fisika tidak menjamin kebenaran pendapat tentang kebijakan moneter, sehingga ini adalah appeal to authority yang keliru."],
    ["Which sentence presents an opposing view most fairly in a scholarly argument on rent control?","Proponents of rent control contend, with some empirical support, that it protects long-term tenants from displacement.",["Some naïve commentators still cling stubbornly to the outdated idea that rent control somehow genuinely helps ordinary tenants.","Rent control is supported only by people who clearly do not understand even the most basic economics.","It is sometimes said that rent control is good for tenants, but this is not really true at all."],"Argumen akademik yang adil menyajikan pandangan lawan dalam bentuk terkuatnya, lengkap dengan dukungan buktinya."],
    ["Which sentence best signposts the structure of a scholarly argument without sounding mechanical?","The argument proceeds in three stages, moving from the historical record to the policy debate and then to its ethical stakes.",["Firstly I will talk about history, secondly about policy, thirdly about ethics, and then at the end I will finally write my conclusion.","This essay will now begin to talk about the topic which has been chosen for discussion in the following pages.","There are three parts in this essay, and they are all very important parts of the overall argument presented here."],"Kalimat ini memetakan alur argumen secara jelas dan menunjukkan logika perpindahan antarbagian, bukan sekadar daftar."],
    ["Which claim is hedged appropriately for a scholarly argument based on one regional case study?","The Bandung case suggests that participatory budgeting can raise turnout, at least where civic associations are already strong.",["The Bandung case proves that participatory budgeting increases voter turnout in every city where it is introduced.","It might perhaps be possible that participatory budgeting could possibly affect voter turnout somewhat in some places under some conditions.","Participatory budgeting is a popular idea that many cities across the world have discussed in recent years."],"Satu studi kasus hanya mendukung klaim terbatas, dan kalimat ini menyatakan kemungkinan sekaligus kondisi berlakunya."],
    ["Objection: 'Peer review is slow and therefore obstructs science.' Which rebuttal is most rigorous?","Delay is a genuine cost, but it is the price of a filtering function that faster alternatives have yet to replicate.",["Peer review is not slow at all, and anyone who says so has obviously never published anything in a scholarly journal.","Science has always been a slow process, so there is really no reason for anyone to worry about this issue.","Peer review is used by almost every academic journal, which proves that it must be an effective system."],"Bantahan ini mengakui biaya yang nyata lalu menunjukkan fungsi yang belum tergantikan, sehingga adil sekaligus kuat."],
    ["Which revision removes redundancy most effectively? 'The final outcome of the research study was a completely unanticipated surprise to the investigators.'","The study's outcome surprised the investigators.",["The final outcome of the study was a surprise to the investigators.","The research outcome was a completely unanticipated surprise.","The study's final outcome was an unanticipated surprise to them."],"'Final outcome', 'research study', dan 'unanticipated surprise' bersifat redundan, dan revisi ini menghapus semuanya tanpa kehilangan makna."],
    ["Which topic sentence best opens a paragraph arguing that citation counts are a flawed measure of research quality?","Citation counts measure attention rather than quality, and the two diverge most sharply in contested fields.",["Citation counts are numbers that show how often an article has been cited by other researchers.","Many universities use citation counts, and some researchers have a very large number of citations to their name.","In this paragraph I am going to discuss citation counts and some of the problems that they have."],"Kalimat topik ini membuat klaim argumentatif yang jelas dan memberi arah analisis bagi paragraf."],
    ["Why should a scholarly argument on 'meritocracy' define the term early?","Because the argument's validity depends on which of several competing meanings is in play",["Because examiners award extra marks for every definition included in an essay","Because defining terms always makes an essay longer and therefore makes it sound more academic","Because readers cannot be expected to know any academic vocabulary at all"],"Istilah yang diperdebatkan seperti 'meritocracy' punya banyak makna, sehingga validitas argumen bergantung pada definisi yang dipakai."],
    ["Complete: 'The correlation is robust across all twelve datasets. ___ it does not, on its own, establish a causal mechanism.'","Robust as it is, however,",["Because it is so robust,","Consequently, and for this reason,","In other words, and above all,"],"Struktur 'Robust as it is, however' mengakui kekuatan korelasi sambil memperkenalkan batasannya secara kontras."],
    ["Which conclusion best ends a scholarly argument that open-access publishing benefits researchers in the Global South?","Open access widens who may read research; whether it widens who may publish it remains the more pressing question.",["In summary, open-access publishing is good for researchers and should therefore be supported by everyone.","Open access also has disadvantages, such as article processing charges, which are often extremely high.","To conclude, I have shown that open access is clearly the best publishing model in the entire history of modern science."],"Kesimpulan ini menyintesis argumen dan membuka implikasi yang lebih tajam, bukan hanya mengulang tesis."],
  ],
  3: [
    ["Which sentence best frames a critical literature review on emerging research on digital attention?","Research on digital attention has grown rapidly, but its findings resist comparison because 'attention' is measured in incompatible ways.",["Many researchers have written about digital attention, and their articles are listed below in the order in which they originally appeared in print.","Digital devices are destroying our attention spans, as every single study on the subject has clearly and repeatedly shown.","This literature review will look at some articles about phones, screens, and how people manage to pay attention to things."],"Bingkai ini menilai keadaan riset secara kritis dan menunjukkan masalah utama yang akan dibahas tinjauan pustaka."],
    ["The model text notes that consequences are 'distributed unevenly across groups, institutions, and time'. In a literature review, this most directly encourages the writer to:","examine whether findings hold equally for different populations and periods",["list the studies strictly in the order in which they were originally published","include only those studies that support the writer's own position","avoid discussing any differences between the studies under review"],"Gagasan distribusi yang tidak merata mendorong penulis menguji apakah temuan berlaku sama pada kelompok dan periode berbeda."],
    ["Which question from the lesson's revision checklist is most relevant when a review draft states that 'all studies agree'?","Have I qualified claims where evidence is limited?",["Does each paragraph perform a clear function?","Is the register appropriate for a C2 reader?","Does the conclusion synthesise rather than repeat?"],"Klaim 'all studies agree' adalah generalisasi berlebihan, sehingga pertanyaan tentang kualifikasi klaim paling relevan."],
    ["Which topic sentence best organises a review paragraph thematically rather than study by study?","Studies of adolescent sleep diverge mainly over measurement: self-report studies find strong effects, actigraphy studies weaker ones.",["Smith (2018) studied adolescent sleep, and then a couple of years later Lee (2020) also studied adolescent sleep in a little more detail.","The first study I found was by Smith, who looked at sleep patterns among a group of teenagers living in the city of Leeds.","Adolescent sleep is a very important topic that has interested a large number of researchers for several decades now."],"Kalimat ini mengorganisasi paragraf berdasarkan tema (perbedaan metode pengukuran), bukan meringkas studi satu per satu."],
    ["Which sentence most precisely identifies a research gap?","Although microplastic exposure in adults is well documented, few studies have tracked exposure longitudinally in infants.",["More research is always needed on microplastics, since it is clearly a very important and timely topic for scientists and the public.","Nobody has ever studied microplastics at all, so this whole area of research is completely unexplored.","Microplastics have now been studied by many different researchers in a large number of countries."],"Celah riset yang baik menyebut apa yang sudah diketahui dan secara spesifik apa yang belum diteliti."],
    ["Choose the most critical yet fair evaluation: 'Hartono's (2021) sample of 40 urban graduates ___ the generalisability of her conclusions.'","constrains",["invalidates","confirms","extends"],"Sampel kecil dan homogen membatasi (constrains) generalisasi tanpa membatalkan seluruh temuan, sehingga penilaiannya adil."],
    ["Spot the weakness in this review sentence: 'Brown (2015) said that gamification works. Patel (2017) said that it works too. Ng (2019) said it does not.'","It reports sources serially without evaluating or relating them",["It cites far too many sources for a single short paragraph","It uses the past tense instead of the present perfect throughout","It fails to include direct quotations from each of the sources"],"Tinjauan pustaka kritis harus menilai dan menghubungkan sumber, bukan hanya melaporkannya secara berurutan."],
    ["Which sentence best reconciles conflicting findings in a review of research on the bilingual cognitive advantage?","The contradiction may be methodological: studies reporting an advantage tend to use smaller samples and looser controls.",["Some studies find a bilingual advantage and some do not, so the question simply cannot be answered by anyone at all at present.","The studies that found no advantage must be wrong, since bilingualism is clearly beneficial for the brain.","Both groups of studies are equally correct, as each of them reflects the honest views of its authors."],"Kalimat ini menawarkan penjelasan metodologis yang masuk akal atas perbedaan temuan, sehingga merupakan sintesis kritis."],
    ["In a literature review, which sentence uses tense most conventionally to report a current consensus?","Most researchers now accept that sleep loss impairs working memory.",["Most researchers had accepted that sleep loss impaired working memory.","Most researchers will accept that sleep loss impairs working memory.","Most researchers were accepting that sleep loss impairs working memory."],"Konsensus yang masih berlaku dilaporkan dengan simple present, seperti 'now accept'."],
    ["Six observational studies, none randomised, report lower anxiety among regular gardeners. Which sentence calibrates this evidence most accurately?","The evidence points consistently in one direction, though its observational design leaves causation open.",["The evidence conclusively proves that gardening reduces anxiety in all adults who take it up on a regular basis.","The evidence is worthless because none of the six studies used a randomised controlled design.","The evidence is mixed and contradictory, as six different studies were carried out on the topic."],"Kalimat ini mengakui konsistensi temuan sambil menyatakan bahwa desain observasional belum membuktikan sebab-akibat."],
    ["Which revision is most concise without losing meaning? 'There are a number of studies that have been conducted which have examined the effects of noise on concentration.'","Several studies have examined how noise affects concentration.",["Noise affects concentration.","There are studies that have been conducted on noise and concentration.","A number of studies which examined noise effects were conducted."],"Revisi ini menghapus struktur 'there are ... that have been conducted which' tanpa mengubah klaim tentang adanya studi."],
    ["Which sentence best positions the writer's own research in relation to the reviewed literature?","Building on this work while addressing its reliance on Western samples, the present study examines attention in Indonesian schools.",["My study is completely different from everything else that has ever been written on this particular topic.","The present study repeats the earlier work exactly, using the very same participants and the same materials.","After reading all of these studies carefully, I decided that I would do a study on something quite similar."],"Kalimat ini menghubungkan studi penulis dengan literatur dan menunjukkan celah spesifik yang diisinya."],
    ["Which citation best suits a review paragraph organised around findings rather than authors?","Peer tutoring appears to benefit tutors as much as tutees (Rahman, 2020).",["Rahman (2020) is a researcher who has written about peer tutoring.","According to Rahman, who wrote in 2020, there is something about tutoring.","Rahman, in her 2020 article, wrote quite a lot about tutors and tutees."],"Sitasi non-integral menonjolkan temuan, sehingga cocok untuk paragraf yang disusun berdasarkan tema."],
    ["Which comment evaluates a study's method rather than merely describing it?","Because participants self-selected into the programme, the reported gains may partly reflect prior motivation.",["The study involved 300 participants from four schools who took part in the programme over a period of six months.","The researchers used a questionnaire and a series of interviews to collect all of their data.","The study was published in a well-known and highly respected journal in the field of education."],"Komentar ini menilai kelemahan desain (seleksi diri) dan dampaknya pada interpretasi, bukan hanya mendeskripsikan metode."],
    ["Which closing sentence best ends a critical literature review?","Taken together, these studies establish the phenomenon but not its mechanism, which is where further work should concentrate.",["In conclusion, a large number of studies on this topic have been reviewed in this chapter of the thesis.","These studies are all very interesting, and each of them makes an important contribution to knowledge.","Overall, the literature shows that everything about this phenomenon is now completely known and fully understood by researchers."],"Penutup ini menyintesis keadaan pengetahuan dan menunjukkan arah riset berikutnya secara spesifik."],
  ],
  4: [
    ["Which opening best suits an executive policy brief on urban adaptation and climate resilience?","Without coordinated drainage investment, Semarang's flood losses are projected to double by 2035; this brief sets out three costed options.",["Climate change is one of the greatest challenges facing humanity in the twenty-first century, and cities are certainly no exception to this general rule.","This brief will talk about climate and cities and about what could maybe be done about some of the problems that they face.","Cities must take radical action on climate immediately, whatever the financial cost may be, because the future depends on it."],"Pembuka policy brief harus langsung menyatakan masalah spesifik, skala, dan apa yang ditawarkan kepada pembuat keputusan."],
    ["According to the model text, why should a policy brief qualify the scope of its central claim?","Because a problem's consequences are distributed unevenly across groups, institutions, and time",["Because policymakers generally prefer briefs that avoid taking any clear position on contested issues","Because qualifying claims makes a brief sound more academic and more impressive","Because longer briefs are more likely to be read in full by busy ministers"],"Teks model menyatakan dampak suatu masalah tersebar tidak merata, sehingga cakupan klaim perlu dibatasi dengan tepat."],
    ["A lesson exercise asks you to cut a 90-word paragraph to 65 words. In a policy brief, which content should go first?","Background detail that does not bear on the decision",["The recommendation and its estimated cost","Figures that quantify the overall scale of the problem","The deadline by which a decision is required"],"Dalam policy brief, latar belakang yang tidak relevan dengan keputusan adalah bagian pertama yang dapat dipangkas."],
    ["Which recommendation is most actionable for a ministry reading a policy brief?","Require all new public buildings above 2,000 m² to include rainwater retention from January 2027.",["The government should think seriously about doing a great deal more for urban water management soon.","It is recommended that something be done about rainwater collection in the near future.","Water is precious, and we must all work together to protect it for our children."],"Rekomendasi ini spesifik tentang apa, untuk siapa, dan kapan, sehingga dapat langsung dilaksanakan."],
    ["Where should the key recommendation appear in an executive policy brief?","In the opening summary, before the supporting analysis",["Only in the final paragraph, after all of the evidence","In an appendix for readers who want more detail","Nowhere explicitly, so that readers can infer it"],"Policy brief menempatkan inti rekomendasi di awal karena pembacanya sibuk dan perlu segera tahu keputusannya."],
    ["Which sentence presents a policy option with its trade-off most clearly?","Option B, congestion-linked parking fees, would raise revenue quickly but may fall hardest on shift workers without transit access.",["Option B is parking fees, which are good in some ways and also bad in others, depending on exactly how you choose to look at them in practice.","Option B is clearly the best option available and has no real drawbacks worth mentioning in this brief.","Option B involves parking fees, a policy that has already been used in a large number of cities worldwide."],"Kalimat ini menyebut manfaat dan biaya opsi secara spesifik, termasuk kelompok yang terdampak."],
    ["Which sentence suits the register of a brief addressed to a parliamentary committee?","The committee may wish to consider extending the subsidy for a further twelve months, pending evaluation.",["You guys should probably keep the subsidy going for another year or so, just to be safe.","We humbly beseech the honourable committee to graciously consent to the subsidy's continuation for another year.","The subsidy must obviously be extended, as anyone who has looked at it can plainly see."],"Register ini formal, sopan, dan lugas tanpa terlalu santai atau berlebihan."],
    ["Spot the main weakness in this brief excerpt: 'Studies show heat deaths are rising. Action is needed.'","It cites no specific evidence and does not say what action is needed or by whom",["It is far too long to be included in an executive summary","It uses an inappropriately informal register for an audience of senior policymakers","It contains a grammatical error in the second sentence"],"Policy brief harus menyebut bukti spesifik dan rekomendasi yang jelas pelakunya, sedangkan kutipan ini terlalu kabur."],
    ["Which projection is appropriately cautious for a brief based on modelling?","Modelling indicates that green roofs could lower peak street temperatures by up to 2°C, depending on coverage.",["Green roofs will lower street temperatures by exactly 2°C in every single district of the city.","Green roofs might do something to temperatures, but nobody can really know what that might be.","Green roofs are popular in Europe and are becoming increasingly fashionable in many of the larger Asian cities as well."],"Proyeksi berbasis model harus menyebut sumbernya, rentang hasil, dan syaratnya, seperti kalimat ini."],
    ["Which version presents cost evidence most efficiently for a busy reader?","Retrofitting costs Rp 4.2 trillion over five years, roughly a third of projected flood losses.",["In terms of the cost of retrofitting, it can be said that the total over five years would be around Rp 4.2 trillion.","Retrofitting is expensive, but it is cheaper than floods.","The costs, which have been calculated by the team, are described in detail in Section 7."],"Versi ini memberi angka, jangka waktu, dan perbandingan yang bermakna dalam satu kalimat ringkas."],
    ["Which section heading is most informative in a policy brief?","Mangrove restoration offers the lowest cost per household protected",["Section 3: Mangroves and coastal protection","Some general thoughts on mangrove restoration","Mangroves: an introduction to the topic"],"Judul bagian yang informatif menyatakan temuan utamanya sehingga pembaca sibuk dapat menangkap pesan dari judul saja."],
    ["Which sentence acknowledges a political constraint without weakening the recommendation?","Although relocation is politically sensitive, a voluntary buy-back scheme can reduce exposure without compulsory moves.",["Relocation is politically sensitive, so it should probably not be recommended, or even mentioned, anywhere in this brief at all.","Some politicians may not like relocation, but their opinions really do not matter in this case.","Relocation is sensitive, and sensitivity is something that all governments have to face sometimes."],"Kalimat ini mengakui kendala politik dan langsung menawarkan desain kebijakan yang mengatasinya."],
    ["A policy brief is being adapted from an academic paper. Which change is most necessary?","Replacing the literature review with a short statement of the evidence's implications",["Adding more methodological detail so as to establish greater credibility with ministers","Including the full reference list in the brief's opening paragraph","Expanding the theoretical framework to demonstrate the team's expertise"],"Pembaca policy brief butuh implikasi bukti bagi keputusan, bukan tinjauan pustaka akademik yang panjang."],
    ["Complete the link: 'Early-warning systems cut flood fatalities by 40% in pilot districts. ___, we recommend extending them to all coastal regencies.'","Given this record",["Nevertheless","By contrast","For the time being"],"'Given this record' menghubungkan bukti keberhasilan dengan rekomendasi sebagai konsekuensi logis."],
    ["Which closing sentence best suits an executive policy brief?","A decision before the March budget round would allow construction to begin ahead of the next monsoon.",["Thank you very much for taking the time to read this brief, which we very much hope you have enjoyed reading.","In conclusion, climate change is a very serious problem that affects every one of us.","Further research is needed before any kind of decision on this matter can be taken."],"Penutup policy brief yang efektif menegaskan urgensi dan tenggat keputusan secara konkret."],
  ],
  5: [
    ["Which sentence best states the purpose in an abstract on the ethical use of artificial intelligence?","This study examines how hospital procurement teams assess fairness claims made by vendors of diagnostic AI.",["Artificial intelligence is a fascinating technology that raises a great many difficult ethical questions for society.","In this paper, we will try to look at some of the ethical issues surrounding artificial intelligence.","AI is fundamentally unethical and must be strictly regulated by every government in the world."],"Pernyataan tujuan abstrak harus spesifik tentang apa yang diteliti, pada siapa, dan dalam konteks apa."],
    ["The model text warns against sounding impressive 'at the expense of clarity'. In an abstract, this most directly means:","stating method and findings plainly rather than in ornamental jargon",["avoiding all technical terms, even those that the field genuinely requires","omitting the results so that readers will open the full paper","writing in the first person singular throughout the abstract"],"Abstrak yang jelas melaporkan metode dan temuan secara lugas tanpa jargon hiasan, meski istilah teknis tetap boleh."],
    ["Which item from the lesson's evaluation vocabulary would a reviewer apply to a study with only 12 participants?","methodologically weak",["consequential","defensible","persuasive"],"Sampel 12 orang menunjukkan kelemahan metodologis, sehingga istilah 'methodologically weak' paling tepat."],
    ["Which order of moves is conventional in an empirical research abstract?","Background, aim, method, results, implication",["Results, background, aim, implication, method","Aim, implication, background, results, method","Method, implication, results, aim, background"],"Abstrak empiris lazimnya bergerak dari latar belakang, tujuan, metode, hasil, lalu implikasi."],
    ["Which results sentence is most informative in an abstract?","Recall rose by 18% among participants who spaced their practice, with no gain in the massed condition.",["The results were very interesting and showed some notable differences between the two groups of participants.","Many important results were found, and they are discussed in detail later in the paper.","Spaced practice turned out to be better."],"Kalimat hasil yang baik menyebut besarnya efek dan perbandingan antarkondisi secara spesifik."],
    ["Which tense combination is most conventional in a research abstract?","Past for method and results; present for conclusions",["Future for method; present perfect for results","Present continuous throughout the whole abstract","Past perfect for aims; simple past for all conclusions"],"Metode dan hasil dilaporkan dengan past tense, sedangkan kesimpulan yang masih berlaku memakai present tense."],
    ["Spot the problem in this abstract's final sentence: 'These findings prove that mindfulness cures exam anxiety.'","It overstates what a single study can establish",["It uses the present tense for a conclusion","It is too short to serve as an abstract's final line","It repeats the topic of the study again"],"Satu studi tidak dapat 'membuktikan' atau 'menyembuhkan', sehingga klaim ini berlebihan."],
    ["An abstract must not exceed 150 words and your draft has 190. Which cut is most appropriate?","Compress the background to a single sentence",["Remove the results and keep the literature context","Delete the method so that the findings stand alone","Cut both the implication and the stated aim"],"Latar belakang adalah bagian yang paling aman diringkas, karena tujuan, metode, dan hasil adalah inti abstrak."],
    ["Which revision best tightens this abstract sentence? 'The aim of this present research study is to make an investigation into the question of why nurses leave rural posts.'","This study investigates why nurses leave rural posts.",["Nurses leave rural posts.","The aim of this study is to make an investigation into why nurses leave.","This present study's aim is investigating the question of nurses leaving."],"Revisi ini mengganti nominalisasi bertele-tele dengan verba langsung 'investigates' tanpa kehilangan isi."],
    ["Original abstract finding: 'Participants exhibited significantly reduced cortisol reactivity following the intervention.' Which version best suits a lay summary?","After the programme, participants' bodies showed a smaller stress response.",["Participants exhibited significantly reduced cortisol reactivity after the intervention.","The programme completely removed all stress from the participants' lives.","Cortisol is a hormone that is produced by the body's adrenal glands."],"Ringkasan awam menerjemahkan istilah teknis ke bahasa sehari-hari tanpa melebih-lebihkan temuan."],
    ["Which conclusion is best calibrated for a cross-sectional study?","Longer daily commutes were associated with lower reported wellbeing, though causal direction cannot be inferred.",["Long daily commutes directly cause lower levels of wellbeing in all workers, regardless of their job or income level.","Commuting may or may not be related to wellbeing in some way, and it is very hard to say.","Wellbeing is an increasingly important topic for employers in modern workplaces around the world."],"Desain cross-sectional hanya menunjukkan asosiasi, dan kalimat ini menyatakannya dengan batasan yang tepat."],
    ["Which set of keywords is most useful for an abstract on teacher burnout in rural Indonesian schools?","teacher burnout; rural education; Indonesia; workload",["teachers; schools; problems; study; results","burnout is a serious problem for many teachers in Indonesia","education; research; paper; findings; data"],"Kata kunci yang baik spesifik dan mencerminkan konsep inti studi sehingga mudah ditemukan dalam pencarian."],
    ["Which sentence reports the method most efficiently?","We interviewed 24 midwives across three provinces and analysed the transcripts thematically.",["We carried out some interviews with midwives, and then after that we analysed what they told us.","Interviews were conducted, and the data that were collected from them were subsequently analysed.","The participants in this study were all midwives."],"Kalimat ini memuat sampel, lokasi, dan teknik analisis secara ringkas dan lengkap."],
    ["Which sentence best states the significance of a study in an abstract?","The findings suggest that brief school-based screening could identify reading difficulties two years earlier than current practice.",["This study is extremely significant and will certainly change the way that education works forever.","The significance of this study is that it is significant for the field of education in general.","This study was carried out over a period of eighteen months in four different primary schools."],"Pernyataan signifikansi yang baik menjelaskan manfaat konkret temuan dengan hedging yang tepat."],
    ["Spot the main weakness: 'In this paper, we will first introduce the background, then describe the method, and later discuss the findings.'","It describes the paper's structure instead of reporting its content",["It uses the first person, which abstracts never allow","It uses the future tense, which is always ungrammatical in academic writing","It is too concise to be useful as a research abstract"],"Abstrak harus melaporkan isi penelitian (temuan dan implikasi), bukan sekadar menjelaskan urutan bagian makalah."],
  ],
  6: [
    ["Which position statement best suits a formal position paper on university access and social mobility?","The Association holds that contextual admissions should be expanded, provided that support continues beyond the point of entry.",["University should be completely free for everyone, no matter what the cost, starting from the beginning of the next academic year.","There are many views on university access, and every one of them has at least some merit worth considering.","We think universities are kind of unfair to poorer students in a lot of ways, and that really needs to change."],"Pernyataan posisi ini jelas, formal, dan memuat syarat yang membuatnya dapat dipertahankan."],
    ["The writing task requires 'careful qualification'. In a position paper on admissions, which sentence fulfils this?","Contextual offers widen access, although their effect on completion rates is less well established.",["Contextual offers always succeed, and completion rates prove this beyond any reasonable doubt whatsoever.","Contextual offers are controversial, which is why this paper will not discuss them at all.","Contextual offers exist in many countries, especially in Western Europe and North America."],"Kalimat ini menyatakan manfaat yang terbukti sekaligus membatasi klaim pada aspek yang buktinya masih lemah."],
    ["According to the lesson objective, which combination should a C2 position paper display?","Precision, register control, sophisticated cohesion, and purposeful revision",["Length, rare vocabulary, emotional appeal, and frequent deliberate repetition","Speed, informality, personal anecdote, and well-placed humour","Neutrality, brevity, direct quotation, and plain summary"],"Tujuan pelajaran menyebut presisi, kontrol register, kohesi canggih, dan revisi yang bertujuan."],
    ["Which sentence best establishes the organisation's stake in the issue?","As the body representing 140 vocational colleges, the Council has a direct interest in credit-transfer rules.",["We care very deeply about this issue because it is so important to so many people.","Many organisations have opinions about credit transfer, and ours is one of them.","This paper has been written by people who know a great deal about colleges."],"Kalimat ini menjelaskan siapa organisasi itu dan mengapa ia berkepentingan, sehingga membangun kredibilitas."],
    ["Which feature most distinguishes a position paper from a newspaper editorial?","Its systematic grounding of the stance in evidence and stated policy principles",["Its use of a provocative headline designed to attract a broad general readership","Its reliance on vivid personal stories rather than on data","Its deliberate avoidance of any explicit recommendation"],"Position paper mendasarkan sikapnya secara sistematis pada bukti dan prinsip kebijakan, bukan pada retorika publik."],
    ["Objection: 'Quotas lower academic standards.' Which response best suits a position paper?","Evidence from institutions with quotas shows no decline in degree outcomes once transition support is provided.",["This objection is offensive and simply reflects long-standing prejudice against disadvantaged students from poor families.","Standards are unimportant compared with fairness, so the objection is irrelevant here.","Some people believe this, but we respectfully happen to think otherwise."],"Tanggapan terbaik membantah keberatan dengan bukti dan menyebut kondisi pendukungnya."],
    ["Which sentence articulates a guiding principle rather than a specific measure?","Public funding should follow students' needs rather than institutions' prestige.",["Grants should rise by 12% next year for students from the lowest income quintile.","Applications will open on 1 March and close on 30 April each year.","Universities must publish their admissions data by postcode annually."],"Kalimat ini menyatakan prinsip umum yang mendasari kebijakan, sedangkan pilihan lain adalah langkah teknis."],
    ["Which transition best moves from the principles section to the recommendations section?","Translating these principles into practice requires three specific measures.",["On the other hand, there are some principles that we have not yet discussed.","Moreover, principles are important in many different areas of life.","In conclusion, we have now reached the end of this position paper."],"Transisi ini merujuk ke bagian sebelumnya dan secara logis mengantar pembaca ke rekomendasi."],
    ["Spot the weakness: 'It is universally acknowledged by all experts that scholarships are the only solution.'","It asserts a false consensus and an unsupported absolute",["It is too tentative to state a clear position","It uses the passive voice, which formal papers always avoid","It contains a subject-verb agreement error"],"Klaim 'all experts' dan 'the only solution' adalah konsensus palsu dan absolut tanpa bukti."],
    ["Which sentence is in the most suitable register for a position paper submitted to a ministry?","We recommend that the Ministry review the eligibility threshold in consultation with student unions.",["The Ministry has totally messed up the eligibility threshold, and frankly everyone in the sector already knows it.","We would be ever so grateful if the Ministry might possibly look at things at some stage.","Eligibility thresholds: bad. Review needed. Urgently. Student unions agree with us."],"Kalimat ini formal, langsung, dan konstruktif, sesuai register dokumen untuk kementerian."],
    ["Which sentence limits the scope of the position most appropriately?","Our recommendations concern undergraduate admissions only; postgraduate funding raises distinct questions.",["Our recommendations apply equally to every level of education in every country of the world, without exception.","We are not entirely sure what our recommendations apply to at this stage of the process.","Our recommendations are general in nature and therefore have no specific scope as such."],"Kalimat ini membatasi cakupan secara eksplisit dan menjelaskan alasannya."],
    ["Which sentence integrates evidence most persuasively into the paper's argument?","Only 9% of students from the poorest decile enrol in university, a gap that tuition support alone has not narrowed.",["There is a statistic of 9% which is about students who come from the poorest decile of all households in the country.","Statistics show many things about students, and some of the things they show are quite worrying.","As everyone already knows, students from poor families very rarely go on to university."],"Bukti ini diberi angka spesifik sekaligus dikaitkan langsung dengan argumen tentang keterbatasan bantuan biaya."],
    ["Which revision is most concise? 'At this point in time, it is our considered view that the policy in question should be subject to a review.'","We believe the policy should now be reviewed.",["Review the policy.","At this time, it is our view that the policy should be subject to review.","In our considered view, the policy in question should be reviewed."],"Revisi ini mempertahankan sikap penulis dan unsur waktu sambil membuang frasa bertele-tele."],
    ["Which sentence best addresses the cost of the proposed position?","The proposal would cost an estimated Rp 900 billion annually, partly offset by lower dropout-related losses.",["Cost is not an issue at all, because education is priceless for everyone involved.","The proposal may cost some money, but it is honestly hard to say exactly how much.","Costs will be discussed at a later date by other people in another document."],"Kalimat ini memberi estimasi biaya yang konkret dan menyebut penghematan yang mengimbanginya."],
    ["Which closing sentence best suits a formal position paper?","The Association stands ready to contribute data and expertise to the consultation these recommendations require.",["We hope that you will agree with us, because we are obviously right about this.","That is all we have to say on the matter of university access for the moment.","University access is a fascinating topic with a very long and complex history."],"Penutup ini formal, menegaskan peran organisasi, dan mengarah pada tindak lanjut yang konkret."],
  ],
  7: [
    ["Which opening line gives an editorial on technology, convenience, and civic life a distinct but controlled voice?","Every app that spares us a trip to the town hall also spares us the neighbours we would have met there.",["Technology is everywhere these days, and it affects almost every area of our lives in some way or another.","Apps are evil, and anyone who uses them is personally helping to destroy local democracy.","This editorial is going to discuss technology and the ways in which it relates to civic life."],"Kalimat ini memiliki suara khas melalui paradoks yang tajam namun tetap terkendali dan relevan dengan topik."],
    ["The model text describes ideal style as 'formal but not inflated'. Which editorial sentence best matches this?","The council's decision deserves scrutiny, not because it is radical, but because it was taken in haste.",["The council's decision is, verily, a most egregious and calamitous blunder of truly epochal and historic magnitude.","The council's decision is dumb, and the people who made it really should have known better.","The council made a decision, and it is a decision that has now been made by the council."],"Kalimat ini formal dan tegas tanpa diksi yang berlebihan, sesuai prinsip 'formal but not inflated'."],
    ["The writing task asks for one concession. In an editorial against cashless-only shops, which concession best serves the argument?","Cashless payment is undeniably faster, and that is no small thing; but speed is not the only public good at stake.",["Cashless payment has some advantages, but none of them are really worth mentioning in this editorial.","Admittedly, cash is old-fashioned, and old-fashioned things should generally be replaced by newer and more efficient ones.","Some readers may disagree with this editorial, which is of course their democratic right."],"Konsesi ini mengakui keunggulan nyata lalu membelokkannya untuk memperkuat argumen utama."],
    ["Spot the weakness: 'The developer, who lives in a gated estate, has no right to an opinion on public parks.'","It attacks the speaker instead of the argument",["Its relative clause is grammatically incorrect","It is too cautious to work as an editorial claim","It relies on statistics without citing a source"],"Kalimat ini adalah serangan ad hominem: menolak pendapat karena siapa orangnya, bukan karena isi argumennya."],
    ["Which sentence uses balanced contrast most effectively in an editorial on food waste?","A society that measures success by what it consumes should not be surprised by what it wastes.",["Food waste is bad, and it is also very wasteful of both food and money in our homes and restaurants.","We waste food, and also we consume food, in our society as it exists today.","Food waste, food waste, food waste: it really is everywhere we look these days."],"Kalimat ini memakai kontras seimbang (consumes/wastes) untuk menyampaikan kritik yang mudah diingat."],
    ["Which sentence expresses strong disapproval while keeping editorial credibility?","Closing the night clinic was not merely unwise; it was done without consulting a single patient.",["Closing the night clinic is the worst crime in the entire history of this city and of its council.","It could perhaps be suggested that the closure was possibly not entirely ideal.","The night clinic is now closed, which some people may not like very much."],"Kalimat ini tegas namun didukung fakta spesifik, sehingga kritiknya kredibel dan tidak histeris."],
    ["Which sentence best grounds an editorial claim in concrete detail?","Since the post office closed, pensioners in Kemuning have travelled 14 kilometres to collect their payments.",["Since the post office closed, things have been really hard for lots of people in the area, especially the older ones.","Post offices are important institutions that every town in the country should have.","The closure has had consequences that are very serious indeed for the whole community."],"Detail konkret (lokasi, kelompok, jarak) membuat klaim editorial lebih meyakinkan daripada pernyataan umum."],
    ["Which closing sentence gives an editorial on municipal Wi-Fi tracking a precise call to action?","Councillors should vote down Thursday's motion and commission an independent privacy audit first.",["Everyone should think carefully about Wi-Fi and what it really means for all of us.","Something must be done about this before it is too late for our city and for all of the people who live here.","Wi-Fi is the future, and the future, as we all know, is always on its way."],"Ajakan bertindak yang efektif menyebut siapa yang harus bertindak, apa tindakannya, dan kapan."],
    ["Which headline best suits a quality-newspaper editorial opposing facial recognition in schools?","Schools are for learning, not for surveillance",["Facial recognition: a discussion of several issues","SHOCKING! Cameras are WATCHING your kids!!","What do you think about cameras in our schools?"],"Judul ini menyatakan sikap dengan tegas dan ringkas tanpa sensasionalisme."],
    ["Which use of 'we' is most effective in an editorial?","We have grown used to convenience; we have not yet counted what it costs our neighbourhoods.",["We, the writers of this editorial, are now going to give you our own opinion on this matter.","We think, and we believe, and we really feel that this is all quite wrong.","We cannot say whether this is right, as we have not yet looked into it ourselves."],"'We' di sini melibatkan pembaca dalam tanggung jawab bersama dan membangun argumen secara retoris."],
    ["Which sentence best turns a concession into a rebuttal?","Yes, delivery apps have kept many small restaurants afloat; they have also quietly taken a third of their margins.",["Delivery apps have helped many restaurants, and that is exactly why they are good for everyone involved in the business.","Delivery apps are bad, although nobody can deny that they are bad in several ways.","Some say delivery apps help restaurants, and that may be true, or it may not be true."],"Kalimat ini mengakui manfaat lalu langsung menghadirkan biaya tersembunyi yang membalik penilaian."],
    ["Which revision sharpens this editorial sentence most? 'It is a fact that is quite clear that the new parking rules are in many ways rather unfair to residents.'","The new parking rules are unfair to residents.",["The rules are unfair.","It is clear that the new parking rules are rather unfair in many ways.","The new parking rules, in many ways, are quite clearly rather unfair."],"Revisi ini menghapus frasa pengisi dan pelemah sehingga klaim editorial menjadi tajam tanpa kehilangan informasi."],
    ["Which sentence uses a statistic to sharpen, rather than inflate, an editorial point on local journalism?","Two in five regencies now have no full-time reporter covering their council meetings.",["Local journalism is basically dead everywhere, and no one is reporting anything at all.","Many journalists have lost their jobs, which is very sad for them and their families.","Statistics show that journalism is changing in a lot of different and worrying ways."],"Statistik spesifik ini mempertajam argumen tanpa melebih-lebihkan keadaan."],
    ["Which sentence uses irony with appropriate restraint?","The city's new 'smart' parking meters are clever enough to charge us, if not to accept our cards.",["The meters are stupid, the council is stupid, and this whole plan is completely and utterly stupid.","The parking meters are smart, which is good, and they are also quite new.","Parking meters exist in many cities and are used to collect money from drivers."],"Ironi ini halus dan tepat sasaran sehingga mengkritik tanpa kehilangan kesopanan editorial."],
    ["Which sentence best moves an editorial from the problem to the alternative it proposes?","There is a better model, and it is already working two hours down the coast.",["Furthermore, there are many other problems that we could also discuss here at some length.","In conclusion, the problem is very serious and also very complicated.","On the other hand, some people think there is no problem at all."],"Kalimat ini menjadi jembatan yang jelas dari masalah ke solusi dan menimbulkan rasa ingin tahu pembaca."],
  ],
  8: [
    ["Which thesis best suits a critical reflective essay on failure as evidence of learning?","My failed first translation taught me less about vocabulary than about how readily I had mistaken fluency for understanding.",["Failure is bad, but sometimes it can also be good, depending on the particular situation and on the individual person who is involved.","Everyone fails sometimes, and failing is simply a normal and natural part of human life for all of us.","I failed once, and it was very embarrassing, and I never want to experience anything like that again."],"Tesis reflektif ini spesifik dan menunjukkan pergeseran pemahaman penulis, bukan sekadar perasaan."],
    ["The model text says the conclusion should explain 'what the reader should now understand differently'. In a reflective essay, the ending should therefore:","articulate the shift in the writer's understanding and its wider significance",["repeat all the details of the experience again in strict chronological order","apologise for the mistakes described in the body of the essay","introduce a new and unrelated experience for the sake of contrast"],"Penutup esai reflektif menjelaskan perubahan pemahaman dan maknanya yang lebih luas, sesuai teks model."],
    ["The writing task requires 'careful qualification'. Which reflective sentence best meets it?","The setback was instructive, though I suspect I have since overstated how much it changed my habits.",["The setback changed absolutely everything about me, permanently and forever.","I learned everything I will ever need to know from that single setback.","The setback was a setback, and it set me back for quite some time."],"Kalimat ini jujur membatasi klaim tentang dampak pengalaman, menunjukkan kualifikasi yang cermat."],
    ["Which sentence shows the most critical distance from a personal experience?","At the time I read the supervisor's silence as hostility; in retrospect, it may simply have been fatigue.",["My supervisor was silent the whole time, which was really rude and very upsetting for me and for my colleagues.","I remember the supervisor's silence and the pale green colour of the office walls.","Silence can mean many different things in many different cultures around the world."],"Kalimat ini membandingkan tafsiran dulu dan sekarang, sehingga menunjukkan jarak kritis terhadap pengalaman."],
    ["Which sentence best connects reflection to a theoretical lens without letting theory displace the experience?","Schön's reflection-in-action helps explain why I improvised, though it says less about why I froze first.",["Schön (1983) wrote a famous book about reflection, which a great many people have read.","According to many theorists, reflection is very important for everybody in every profession and at every stage of life.","I did not use any theory, because my experience speaks perfectly well for itself."],"Teori dipakai untuk menjelaskan pengalaman dan sekaligus diuji batasnya, sehingga refleksi tetap berpusat pada pengalaman."],
    ["Spot the main weakness: 'The internship was amazing and I learned so much and grew as a person.'","It asserts growth without specifying what changed or how",["It uses the simple past tense to describe an event in the past","It is written in the first person singular","It is too critical of the internship provider"],"Refleksi kritis harus menyebut perubahan yang spesifik dan prosesnya, bukan klaim umum tentang 'tumbuh'."],
    ["Which sentence best acknowledges the limits of self-report in reflection?","Memory is a partial witness, and my account of that month is inevitably shaped by how it ended.",["My memory of that month is perfect, so this account is entirely accurate in every single detail.","I cannot remember anything about that month, so I will not reflect on it at all.","Memory is something that psychologists have studied carefully for many years."],"Kalimat ini mengakui bahwa ingatan bersifat selektif, menunjukkan kesadaran kritis terhadap sumber refleksi."],
    ["Draft: 'I missed the deadline because I rewrote the introduction six times.' Which follow-up sentence interprets rather than extends the narrative?","That compulsion to perfect the opening, I now see, was a way of postponing the harder argument.",["Then I rewrote the conclusion four times as well, which also took a very long time to finish properly.","The introduction was about water policy in several coastal districts of Java.","My lecturer gave me a lower mark because the essay was submitted late."],"Kalimat ini menafsirkan makna perilaku penulis, bukan sekadar menambah kejadian berikutnya."],
    ["Which sentence balances personal voice and academic register?","I came to recognise that my reluctance to ask questions reflected an assumption about status, not ignorance.",["Honestly, I was just super shy and didn't wanna look dumb in front of everyone else in the seminar room, you know?","It was recognised by the author that the author had been reluctant to ask any questions.","One's reluctance, being of a most profound nature, did manifest itself most visibly."],"Kalimat ini memakai 'I' secara wajar dengan bahasa analitis yang formal, cocok untuk esai reflektif."],
    ["Which sentence evaluates a failure without excessive self-criticism?","The pitch failed largely because I had not tested it on a real audience, a gap that is easily remedied.",["The pitch failed because I am hopeless and will never be good at anything I try.","The pitch did not fail; the audience simply failed to understand what I was trying so hard to say to them.","The pitch failed, but failures happen to everyone, so it really does not matter."],"Evaluasi ini menyebut penyebab spesifik dan langkah perbaikan, tanpa menyalahkan diri berlebihan atau orang lain."],
    ["Which sentence best generalises from personal experience responsibly?","My experience cannot speak for all trainees, but it suggests why public feedback may be heard as judgement.",["My experience clearly proves that all feedback should always be given in private.","Everyone feels exactly the same way I did about feedback, without any exception.","Feedback is something that happens in many workplaces every single day."],"Generalisasi ini dibatasi dengan jujur namun tetap menarik implikasi yang bermakna."],
    ["Which revision removes the redundancy while keeping the retrospective framing? 'Looking back on it now in hindsight, I can see in retrospect that I was wrong.'","In hindsight, I can see that I was wrong.",["I was wrong.","Looking back now in hindsight, I can see I was wrong.","Looking back, in retrospect, I can now see I was wrong."],"'Looking back', 'in hindsight', dan 'in retrospect' bermakna sama, jadi cukup satu yang dipertahankan."],
    ["Which structure best suits a critical reflective essay?","Brief account of the experience, analysis through a lens, evaluation, and implications",["A long chronological narrative followed by a single one-line moral","A list of feelings in order of intensity, followed by a summary","Literature review, method, results, and a formal discussion section with recommendations"],"Esai reflektif kritis menyeimbangkan deskripsi singkat dengan analisis, evaluasi, dan implikasi."],
    ["Which sentence best uses a conditional to reflect on an alternative course of action?","Had I shared the draft earlier, the flaw in the sampling might have surfaced while it could still be fixed.",["If I share the draft earlier, the flaw will be fixed by somebody else on the team.","If I would have shared the draft, the flaw would be fixing much earlier on.","When I shared the draft, the flaw was there, as flaws always tend to be."],"Kondisional ketiga dengan inversi 'Had I...' tepat untuk merefleksikan alternatif di masa lalu."],
    ["Which closing sentence best ends a critical reflective essay on a failed volunteering project?","What I take from the project is not a lesson in resilience but a suspicion of my own good intentions.",["In conclusion, volunteering is good, and everyone should try it at least once in their life, if possible.","The project ended in June, and I went back to university at the beginning of August.","Overall, I think the project was a failure, as I already said at the very start."],"Penutup ini menyintesis refleksi menjadi wawasan yang tajam dan tidak klise."],
  ],
  9: [
    ["Which thesis best suits a comparative analytical essay on remote work and organisational culture?","Fully remote and hybrid firms both erode informal mentoring, but hybrid firms do so unevenly, creating a two-tier culture.",["Remote work and office work are two different ways of working, and each has its own particular advantages and disadvantages.","Remote work is better than office work in every way that matters to employees and to their managers.","This essay compares remote work and organisational culture in several different companies around the world."],"Tesis komparatif ini menyebut persamaan dan perbedaan yang spesifik serta implikasinya."],
    ["The writing task asks for 'two developed sections'. In a comparative essay, which organisation of those sections is most analytical?","Each section addresses one criterion and compares both cases within it",["Each section describes one case fully, with no reference to the other one","One section lists similarities and the other lists differences","Each section summarises a different source on the general topic"],"Pengorganisasian per kriteria memaksa perbandingan langsung, sehingga lebih analitis."],
    ["Which phrase from the lesson's language tools best introduces the comparative verdict?","The stronger interpretation is",["More specifically","It would be premature to conclude","In practical terms"],"'The stronger interpretation is' adalah alat sintesis untuk menyatakan penilaian akhir antara dua kemungkinan."],
    ["Which sentence establishes a comparison criterion most precisely?","The two pension systems are compared here by how they distribute longevity risk between the state and the individual.",["The two pension systems are compared here in terms of whether they are good systems or not.","The two pension systems are very different, although they are also similar in some ways.","This section compares the two pension systems because they are an important topic today."],"Kriteria perbandingan yang tepat menyebut aspek spesifik yang diukur, yaitu distribusi risiko."],
    ["Spot the weakness: 'Both Singapore and Jakarta have public transport, so their transport policies are essentially the same.'","It infers equivalence from a superficial shared feature",["It compares two cities instead of comparing two countries","It uses 'essentially', which is too informal","It omits the population of each of the cities"],"Kesamaan dangkal (sama-sama punya transportasi publik) tidak membuktikan kebijakannya sama."],
    ["Complete: 'Finland delegates curriculum design to municipalities. France, ___, sets it centrally.'","by contrast",["similarly","consequently","for instance"],"'By contrast' menandai perbedaan antara desentralisasi Finlandia dan sentralisasi Prancis."],
    ["Which sentence expresses a contrast with the most precise subordination?","Whereas the 1998 reform targeted inflation, the 2016 reform targeted employment, a shift in priority rather than method.",["The 1998 reform targeted inflation, and the 2016 reform targeted employment as well as several other economic things too.","Because the 1998 reform targeted inflation, the 2016 reform targeted employment instead of inflation.","The 1998 reform targeted inflation, so the 2016 reform was a completely different kind of reform."],"'Whereas' tepat untuk kontras, dan frasa penutup menafsirkan makna perbedaan tersebut."],
    ["Which comparative judgement is most carefully qualified?","Translation A is more faithful to the syntax, though arguably less alive to the poem's humour than Translation B.",["Translation A is better than Translation B in every single respect that a reader might possibly care about at all.","Both translations are good, and so it is impossible to compare them in any meaningful way.","Translation A is longer than Translation B by about forty words, mostly in the second stanza."],"Penilaian ini menyebut keunggulan dan kelemahan berdasarkan kriteria berbeda dengan hedging yang tepat."],
    ["Which sentence explains WHY a difference exists rather than simply noting it?","Korean firms adopted remote work more slowly, partly because seniority-based promotion rewards visible presence.",["Korean firms adopted remote work more slowly than firms in the Netherlands did over exactly the same five-year period.","Korean and Dutch firms are different, as anyone can see from the data presented in the table.","Remote work was adopted by firms in both Korea and the Netherlands during the pandemic."],"Kalimat ini memberi penjelasan kausal atas perbedaan, bukan hanya mencatatnya."],
    ["When is a block (subject-by-subject) structure most defensible in a comparative essay?","When the texts are short and the comparison is drawn together explicitly in a final section",["When the writer wants to avoid making any direct comparison at all","When there are more than ten separate criteria to compare","When the essay has no word limit and no clear thesis"],"Struktur blok dapat diterima bila objeknya sederhana dan perbandingan disatukan secara eksplisit di akhir."],
    ["Which sentence uses parallel structure to sharpen a comparison?","The first model rewards loyalty; the second rewards mobility.",["The first model rewards loyalty, while mobility is what gets rewarded in the second.","The first model is about rewarding loyalty, and the second one has mobility.","Loyalty and mobility are rewarded by the two models in rather different ways."],"Struktur paralel 'rewards loyalty / rewards mobility' membuat kontras jelas dan seimbang."],
    ["Which revision is most concise? 'In comparison with the second novel, the first novel, when compared, is more experimental in its form.'","The first novel is formally more experimental than the second.",["The first is more experimental.","Compared with the second, the first novel, in comparison, is more experimental.","The first novel is more experimental in its form when it is compared."],"Revisi ini menghapus pengulangan 'comparison/compared' dan tetap menyebut aspek bentuk."],
    ["Which comparative claim avoids overextending an analogy?","Like a thermostat, the central bank responds to deviations, though unlike one, it must act on forecasts rather than readings.",["The central bank is exactly like a thermostat in every respect, which explains all of its behaviour perfectly and completely, in every case.","A thermostat and a central bank are both important devices that are used in modern society.","The central bank is a thermostat, inflation is the weather, and the economy is the house itself."],"Analogi yang baik menyebut persamaan sekaligus batasnya agar tidak menyesatkan."],
    ["Which concluding sentence best suits a comparative analysis of two flood-management strategies?","Neither strategy is superior in the abstract; the dyke suits land-scarce areas, the floodplain the rest.",["In conclusion, both strategies have their own advantages and disadvantages.","The dyke strategy is the best, and the floodplain strategy is clearly the worst.","Flood management is an important area of public policy around the world."],"Kesimpulan ini memberi penilaian kontekstual yang tegas, bukan sekadar 'ada kelebihan dan kekurangan'."],
    ["Spot the problem: 'Indonesian students spend more hours on homework than the Finnish education budget.'","It compares two items that cannot be meaningfully compared",["It uses the 'more ... than' comparative structure incorrectly","It should use 'fewer' instead of 'more' here","It needs an article before 'Indonesian students'"],"Kalimat ini membandingkan jam belajar dengan anggaran, dua hal yang tidak sebanding."],
  ],
  10: [
    ["Which statement of need best opens a grant proposal for a community education initiative?","In Kampung Pelangi, 38% of adults lack functional literacy, yet the nearest evening class is a ninety-minute bus ride away.",["Education is the key to a better future for everybody in every single community around the world.","We need money for our education project, which is very good and also very important for people.","Many communities have problems, and our community also has a number of problems that need solving."],"Pernyataan kebutuhan yang kuat memberi data spesifik dan menunjukkan kesenjangan yang akan diatasi proyek."],
    ["The model text says a stronger text 'acknowledges a plausible objection'. In a grant proposal, this is best realised as:","a risk section explaining how foreseeable obstacles will be mitigated",["a paragraph criticising rival applicants' proposals in considerable detail","an apology for requesting such a large sum of money","a list of reasons why the funder might reject the bid"],"Dalam proposal hibah, mengakui keberatan diwujudkan melalui bagian risiko beserta strategi mitigasinya."],
    ["The lesson's checklist asks 'Does each paragraph perform a clear function?' Which grant-proposal section mainly shows that the project can actually be delivered?","Implementation plan and timeline",["Statement of need and background","Project vision","Acknowledgements"],"Rencana pelaksanaan dan jadwal berfungsi membuktikan bahwa proyek realistis untuk dijalankan."],
    ["Which objective is most measurable?","By month 12, 150 caregivers will complete a ten-session digital-safety course, with 80% passing the final assessment.",["The project will help caregivers become much more aware of digital safety issues in their daily lives at home and at work.","We hope to reach as many caregivers as we possibly can over the course of the coming year.","Digital safety will be improved in the community through our hard work and many efforts."],"Tujuan ini menyebut jumlah, waktu, dan ukuran keberhasilan sehingga dapat dievaluasi."],
    ["Which sentence best justifies a budget line?","Two part-time facilitators (Rp 96 million) are needed because sessions run in parallel at two village halls.",["We need Rp 96 million for facilitators, as facilitators unfortunately cost quite a lot of money nowadays, of course.","Facilitators are very important people who deserve to be paid well for their hard work.","The facilitator budget is described somewhere else in this proposal, in one of the annexes."],"Justifikasi anggaran yang baik mengaitkan biaya dengan kebutuhan operasional yang spesifik."],
    ["Which sentence best aligns a proposal with a funder's stated priorities?","The project directly advances the Foundation's 2026 priority of intergenerational learning by pairing students with elderly residents.",["We think the Foundation will like our project very much because it is a really nice project.","The Foundation has funded many projects in the past, and ours is simply another project.","Our project is aligned with absolutely everything that the Foundation has ever done."],"Kalimat ini menyebut prioritas pemberi dana secara eksplisit dan menunjukkan cara proyek memenuhinya."],
    ["Which sentence most convincingly addresses sustainability beyond the grant period?","From year two, the district education office has agreed in writing to absorb facilitator costs.",["We are quite sure that the project will continue forever, with or without funding, after the grant ends.","Sustainability is a very important word in modern project management today.","After this grant ends, we will simply apply for another grant from you."],"Komitmen tertulis dari pihak lain adalah bukti keberlanjutan yang konkret."],
    ["Spot the main weakness: 'Our innovative, ground-breaking, world-class project will transform lives.'","It substitutes promotional adjectives for evidence of what will change",["It uses the future tense to describe the project's planned outcomes and activities","It is written in the first person plural","It is too short to serve as a project summary"],"Kata sifat promosi tidak menggantikan bukti atau penjelasan perubahan yang konkret."],
    ["Which sentence describes an evaluation method most credibly?","An external evaluator will compare participants' pre- and post-programme scores against a matched waiting-list group.",["We will evaluate the project by asking participants whether they enjoyed taking part in it.","Evaluation will happen at the end, and the results will certainly be very positive.","Our own staff will decide at the end of the year whether the project has been a success."],"Evaluasi independen dengan pre-test, post-test, dan kelompok pembanding adalah metode yang kredibel."],
    ["Which statement of expected outcomes is best calibrated?","Based on the pilot, we anticipate attendance of around 70%, though harvest seasons may reduce it temporarily.",["Attendance will definitely be 100% for the entire duration of the project, without any exception, whatever the weather.","We have no idea what attendance will be, but we very much hope it will be good.","Attendance is a common challenge for many education projects in rural areas."],"Proyeksi ini didasarkan pada data uji coba dan menyebut faktor risiko yang realistis."],
    ["Which sentence suits the register of a grant proposal?","We request Rp 450 million over 18 months to establish three community reading hubs.",["Please give us Rp 450 million, as we really, really need it for our new reading hubs.","It would be awesome to get Rp 450 million for a few reading hubs.","Rp 450 million is humbly and most respectfully beseeched of you."],"Register proposal hibah lugas, formal, dan spesifik tentang jumlah, jangka waktu, dan tujuan."],
    ["Which revision is most concise? 'The project will be implemented and carried out by a team of staff who are experienced.'","An experienced team will deliver the project.",["Staff will deliver.","The project will be carried out by staff who are experienced in it.","The project will be implemented and delivered by a team."],"Revisi ini menghapus pasangan verba redundan dan klausa relatif tanpa kehilangan informasi."],
    ["Which risk statement is most useful to reviewers?","If volunteer turnover exceeds 30%, a reserve pool trained in month two will fill vacancies within a fortnight.",["There are no risks of any kind associated with this project at all.","Volunteers might leave, which would be a problem for us.","Risk is part of life, and we accept it fully and calmly."],"Pernyataan risiko yang berguna menyebut ambang risiko dan rencana mitigasi yang konkret."],
    ["Which sentence best links an activity to its intended outcome?","Weekly mentoring is designed to build the study routines that, in the pilot, preceded improved exam results.",["Weekly mentoring sessions will take place every week on Saturday mornings.","Mentoring is good, and exam results are also good for students.","There will be mentoring, and there will also be exams at the end."],"Kalimat ini menjelaskan logika perubahan: aktivitas, mekanisme, dan hasil yang didukung bukti."],
    ["Which closing sentence best suits a grant proposal?","With the Foundation's support, the hubs could reach 1,200 learners by 2028 and offer a model for neighbouring regencies.",["Thank you very much, and we really hope that you choose us over all the other applicants.","In conclusion, education is extremely important for every community everywhere.","Please contact us if you have any questions at all about anything in this proposal."],"Penutup ini menegaskan dampak yang terukur dan potensi replikasi, sehingga meyakinkan pemberi dana."],
  ],
  11: [
    ["Which statement of purpose best opens a strategic report on risk management in public institutions?","This report assesses whether the agency's risk register captures emerging cyber threats and recommends three governance changes.",["Risk is everywhere these days, and public institutions face a great many different risks every single day of the year, in every department.","This report is about risk management, which is a very interesting and important topic for institutions.","The agency is terrible at managing risk of every kind, as this report will clearly prove to the board."],"Pernyataan tujuan laporan harus menyebut apa yang dinilai dan apa yang akan direkomendasikan secara spesifik."],
    ["The model text says paragraphs should be 'cohesive but not mechanical'. In a report, which practice best reflects this?","Linking findings by their logical relationship rather than stacking 'Furthermore' and 'Moreover'",["Beginning every single paragraph with a numbered transition word","Avoiding headings so that the report reads as one continuous essay","Repeating the same linking phrase throughout to create consistency"],"Kohesi yang tidak mekanis berarti hubungan antarparagraf ditunjukkan oleh logika, bukan oleh penumpukan kata penghubung."],
    ["In a report on risk management, which finding is stated with the precision the model text demands?","Of 46 high-impact risks, 19 have no named owner and 11 have not been reviewed since 2023.",["Many risks are not managed properly, and some of them have not been looked at for a while.","Risk management is quite weak in some areas of the organisation, but not in others.","There are lots of risks in the register, and the numbers involved are rather worrying."],"Temuan ini tepat karena menyebut angka, kategori, dan waktu secara jelas."],
    ["Which sentence belongs in the 'Findings' rather than the 'Recommendations' section?","Response times to data breaches averaged 9 days, against a target of 72 hours.",["The IT unit should appoint a dedicated breach-response officer early next year.","Breach procedures ought to be reviewed formally every six months.","All staff should receive annual training on reporting incidents."],"Bagian temuan memuat fakta yang diamati, sedangkan pilihan lain berisi saran tindakan."],
    ["Which sentence best prioritises recommendations for senior readers?","Of the five measures, assigning risk owners is the most urgent, as it is a precondition for the other four.",["There are five measures, and they are all equally important in every possible way.","The measures are simply listed in alphabetical order for the reader's convenience.","Senior readers can decide for themselves which of the measures matters most."],"Pembaca senior membutuhkan prioritas yang jelas beserta alasannya."],
    ["Which sentence best suits an impersonal professional report?","Interviews with eight unit heads indicated limited awareness of escalation procedures.",["I talked to eight heads, and honestly they had no clue about escalation at all, to be fair.","We were shocked to discover just how little the unit heads actually knew.","Eight unit heads were interviewed by me, and I found out some things."],"Kalimat ini objektif, formal, dan berfokus pada temuan, sesuai register laporan profesional."],
    ["Spot the main weakness: 'Some issues were identified in certain areas, and improvements are recommended where appropriate.'","It is so vague that no reader could act on it",["It uses the passive voice, which reports must avoid","It is too direct and might offend senior managers","It has too many technical terms for a general reader"],"Kalimat ini tidak menyebut masalah, area, atau perbaikan apa pun, sehingga tidak dapat ditindaklanjuti."],
    ["Which sentence refers to a figure most usefully?","As Figure 3 shows, unresolved risks cluster in procurement, which accounts for 40% of the total.",["Figure 3 is below, and it is a bar chart with a number of bars in it.","Please see Figure 3, which is very interesting and worth a careful look.","There is a figure somewhere in the report that shows some of the risks."],"Rujukan gambar yang baik langsung menyampaikan pola utama yang perlu ditangkap pembaca."],
    ["Which sentence attributes a cause with appropriate caution?","The rise in incidents coincides with the 2024 staff reductions, although other factors cannot be excluded.",["The staff reductions in 2024 directly caused every single incident that has happened in the agency since then.","Incidents rose, and nobody can possibly know why this happened at all.","The rise in incidents was very large and also very concerning for everyone."],"Kalimat ini menunjukkan kemungkinan hubungan sebab tanpa mengklaim kepastian."],
    ["Which revision is most concise? 'It is recommended by the review team that consideration should be given to the possibility of reviewing the policy.'","The review team recommends reviewing the policy.",["Review the policy.","The review team recommends that consideration be given to reviewing the policy.","Consideration should be given by the team to reviewing the policy."],"Revisi ini mengubah pasif dan nominalisasi berlapis menjadi kalimat aktif yang ringkas."],
    ["Which sentence states the limits of a report most professionally?","The review covered head-office functions only; regional offices will be assessed in the second phase.",["We did not have enough time to look at everything, so sorry about that.","The report is limited, like all reports are, in a great many ways.","Regional offices were simply ignored because they are obviously much less important than head office."],"Batasan laporan dinyatakan secara jelas, netral, dan disertai rencana tindak lanjut."],
    ["Which sentence best bridges the findings and recommendations sections?","These gaps share a single root cause, unclear ownership, which the recommendations below address directly.",["Now the findings are finished, and the recommendations section will begin.","In addition, there are some recommendations that we would also like to make.","The findings were found, and so the recommendations are now recommended."],"Kalimat ini merangkum temuan menjadi satu akar masalah dan mengaitkannya langsung dengan rekomendasi."],
    ["A report goes to both the board and technical staff. Which approach serves both audiences best?","A concise decision-focused summary up front, with technical detail in appendices",["A single technical narrative with no summary and no headings","Two contradictory versions with different recommendations","A brief summary only, omitting all of the supporting evidence and technical detail"],"Ringkasan untuk pengambil keputusan dan lampiran teknis untuk staf melayani kedua audiens sekaligus."],
    ["Which sentence is clearest while remaining formal?","The agency should update its continuity plan before the audit in May.",["The undertaking of an update of the continuity plan by the agency prior to the audit is required.","The agency should, like, update the continuity plan before the audit thing.","Continuity plan updating before May auditing is an agency necessity."],"Kalimat ini formal namun lugas, menghindari nominalisasi berlebihan maupun bahasa santai."],
    ["Which concluding sentence best suits a strategic professional report?","Implementing these measures would bring the agency into line with national standards within a single budget cycle.",["In conclusion, risk management is very important for every kind of public institution.","We hope the board will read this report carefully and find it enjoyable.","There are many more risks, but unfortunately we did not have space to discuss them."],"Penutup laporan strategis menegaskan hasil yang dapat dicapai bila rekomendasi dijalankan."],
  ],
  12: [
    ["Which sentence best interprets data on economic inequality and household behaviour?","Households in the lowest quintile spent 61% of income on food and housing, leaving little scope to absorb price shocks.",["The lowest quintile spent 61%, the second 48%, the third 39%, the fourth 31%, and the fifth just 22% of their total income.","Poor households spend a lot of their money and rich households spend less, which is very unfair.","The data about inequality and household spending are all shown in the table above this paragraph."],"Kalimat ini memilih angka penting lalu menafsirkan maknanya, bukan sekadar menyalin tabel."],
    ["The model text warns against assertion without definition. In data commentary, which practice follows this most directly?","Defining how a key variable, such as 'household income', was measured",["Reporting every figure in the table in the order it appears","Using intensifiers such as 'shocking' to highlight the most important figures","Omitting units so that the commentary reads more fluently"],"Mendefinisikan cara pengukuran variabel kunci mencegah klaim yang kabur atau menyesatkan."],
    ["Which phrase from the lesson's qualification tools best prevents a causal overclaim from survey data?","This does not necessarily imply",["The distinction matters because","Taken together","More specifically"],"'This does not necessarily imply' membatasi lompatan dari korelasi ke sebab-akibat."],
    ["A chart shows savings rates for five income groups. Which sentence best selects the salient pattern?","Savings rates rise with income, but the sharpest jump occurs between the third and fourth quintiles.",["The first group saves 2%, the second 5%, the third 7%, the fourth 15%, and the fifth 21%, respectively.","The chart has five bars, one for each of the income groups included in the survey.","Some groups save money, while other groups manage to save even more money."],"Komentar data yang baik menyoroti pola utama dan titik yang paling mencolok."],
    ["Choose the most accurate verb: 'Fuel subsidies ___ from 2.1% to 0.6% of GDP between 2014 and 2015.'","plunged",["edged down","levelled off","fluctuated"],"Penurunan dari 2,1% ke 0,6% dalam satu tahun sangat tajam, sehingga 'plunged' paling tepat."],
    ["Which sentence uses an approximator accurately for a figure of 48.7%?","Just under half of respondents reported borrowing to cover school fees.",["Well over half of respondents reported borrowing to cover school fees.","Exactly half of all respondents reported borrowing to cover school fees.","A small minority of respondents reported borrowing to cover school fees."],"48,7% sedikit di bawah setengah, sehingga 'just under half' adalah perkiraan yang akurat."],
    ["Which sentence handles an outlier most responsibly?","The 2020 figure departs sharply from the trend and probably reflects pandemic disruption rather than structural change.",["The 2020 figure is clearly wrong and has therefore simply been removed from the whole analysis.","The 2020 figure is the most important result and reveals a new and permanent trend.","In 2020 the figure was different from the figures for the other years."],"Kalimat ini mengakui anomali dan menawarkan penjelasan yang hati-hati tanpa membuang data."],
    ["Spot the error: 'Unemployment rose from 4% to 6%, an increase of 2%.'","The rise is two percentage points, which is a 50% increase",["The figures should be written out in words, not numerals","'Rose' should be replaced by the verb 'raised'","The sentence needs a reference to a figure number"],"Kenaikan dari 4% ke 6% adalah 2 poin persentase atau 50%, bukan '2%'."],
    ["Data: regions with higher mobile-money adoption show higher household savings. Which interpretation is most defensible?","Mobile-money adoption is positively associated with savings, though wealthier regions may simply adopt it sooner.",["Mobile money makes households save more money in every region where it is introduced.","There is no relationship at all, because correlation is always meaningless.","Savings and mobile money are both increasing steadily everywhere."],"Interpretasi ini menyatakan asosiasi dan menyebut faktor perancu yang mungkin."],
    ["Which sentence makes the most precise comparison?","Rural households spent nearly twice as much of their income on transport as urban households (14% vs 8%).",["Rural households spent much more on transport than urban households did.","Rural and urban households both spent some of their money on transport.","Urban households spent less, which means that rural ones spent more."],"Perbandingan ini menyebut besaran relatif dan angka pendukungnya secara tepat."],
    ["Why might a data commentary on household income report the median rather than the mean?","Because a few very high incomes can inflate the mean and misrepresent the typical household",["Because the median is always larger and therefore more impressive","Because the mean cannot be calculated for any income data","Because readers find the word 'median' more formal"],"Distribusi pendapatan yang timpang membuat median lebih mewakili rumah tangga pada umumnya."],
    ["Which revision is most concise? 'As can be seen from the data that is shown in Table 2, it is clear that rents increased.'","Table 2 shows that rents increased.",["Rents rose.","As can be seen in Table 2, it is clear that rents went up.","The data shown in Table 2 make it clear that rents increased."],"Revisi ini mempertahankan rujukan tabel dan temuan sambil membuang frasa berulang."],
    ["Which sentence best links a data point to its policy implication?","Because a third of borrowers under 25 rely on unlicensed lenders, consumer-protection rules may be missing those most exposed.",["A third of borrowers under 25 use unlicensed lenders, which is exactly one third of them.","Young people borrow money from many different kinds of lenders in the city.","Unlicensed lenders are bad, and the government should ban them all today."],"Kalimat ini menghubungkan data dengan implikasi kebijakan secara logis dan hati-hati."],
    ["Which sentence best qualifies findings from an online survey?","Because the survey was conducted online, households without internet access are likely under-represented.",["The online survey represents every household in the country perfectly.","Online surveys are modern and are therefore more accurate than others.","The survey was online, which was very convenient for the researchers."],"Kalimat ini menjelaskan bias sampel yang spesifik akibat metode survei daring."],
    ["Which sentence best describes figures that barely changed?","The Gini coefficient remained broadly stable, hovering around 0.38 throughout the decade.",["The Gini coefficient soared dramatically to around 0.38 over the course of the whole decade.","The Gini coefficient did various things around 0.38 during the decade.","The Gini coefficient collapsed to 0.38 throughout the whole decade."],"'Remained broadly stable' dan 'hovering around' tepat untuk data yang hampir tidak berubah."],
  ],
  13: [
    ["Which issue statement best opens a legal-style analysis of privacy obligations in digital contracts?","The question is whether a clause buried in a 9,000-word licence can constitute informed consent to the sale of location data.",["Privacy is a fundamental human right, and technology companies should always respect it in absolutely everything that they do online.","Digital contracts are very long these days, and almost nobody ever reads them before clicking to agree.","This analysis is about privacy and contracts and the various ways in which the two of them relate."],"Analisis bergaya hukum dibuka dengan rumusan isu yang spesifik dan dapat dijawab."],
    ["The model text's sequence 'define, qualify, acknowledge an objection, defend' corresponds most closely to which legal-analysis pattern?","Issue, rule, application, counter-argument, conclusion",["Introduction, story, moral, and a final ending","Summary, opinion, quotation, and a final recommendation","Background, method, results, and discussion"],"Pola analisis hukum (isu, aturan, penerapan, kontra-argumen, kesimpulan) sejalan dengan urutan dalam teks model."],
    ["The writing task asks for a concession. In an analysis of online privacy terms, which concession is most appropriate?","It may be conceded that the user clicked 'I agree'; the issue is whether that act meets the statutory standard of consent.",["The user clicked 'I agree', so the analysis must inevitably end in the company's favour on every single point that is raised.","Users never read their contracts, so no concession of any kind is necessary in this analysis.","Some people think that clicking a button counts as consent, but those people are not lawyers."],"Konsesi ini mengakui fakta yang merugikan lalu memindahkan fokus ke pertanyaan hukum yang menentukan."],
    ["Which modal expresses a legal obligation most precisely?","The controller shall notify the authority within 72 hours.",["The controller might notify the authority within 72 hours.","The controller could notify the authority within 72 hours.","The controller would like to notify the authority in 72 hours."],"Dalam bahasa hukum formal, 'shall' menyatakan kewajiban, sedangkan modal lain hanya kemungkinan atau keinginan."],
    ["Rule: a term is unfair if it causes a significant imbalance to the consumer's detriment. Which sentence applies this rule to the facts?","Because the clause lets the provider alter fees unilaterally while denying the user any exit, it creates precisely such an imbalance.",["Unfair terms are a well-known problem in consumer law in many jurisdictions across the world today.","The rule about unfair terms is set out very clearly in the relevant section of the statute.","The provider is a very large company and is therefore probably acting unfairly towards its users."],"Kalimat ini menerapkan unsur aturan pada fakta spesifik klausa, yang merupakan inti tahap 'application'."],
    ["Which sentence best distinguishes a precedent?","Unlike in Re Harlow, where the term was individually negotiated, the present clause was offered on a take-it-or-leave-it basis.",["Re Harlow is quite an old case, so it simply does not apply to anything that happens today.","Re Harlow was decided by a very famous judge, and therefore we agree with it entirely.","The present case is the same as Re Harlow in every single material respect that matters."],"Membedakan preseden berarti menunjukkan perbedaan fakta material yang membuat putusan lama tidak berlaku."],
    ["Which sentence predicts a court's view with suitable caution?","A court would likely regard the waiver as unenforceable, though the point has not been tested on appeal.",["A court will certainly strike down the waiver, and there is no reasonable doubt about this outcome whatsoever.","Nobody can say what a court would do, so making any prediction is pointless.","Courts are sometimes unpredictable, like many other public institutions."],"Prediksi ini menyatakan kemungkinan kuat sekaligus menyebut ketidakpastian hukum yang nyata."],
    ["Spot the drafting problem: 'The user may share data with partners and affiliates who are not based in the EU.'","It is unclear whether 'not based in the EU' qualifies partners, affiliates, or both",["It uses 'may', which is never acceptable in formal legal drafting of any kind whatsoever","It is too short to count as a valid contractual clause","It should use 'whom' instead of 'who' in the relative clause"],"Klausa relatif ini ambigu cakupannya, dan ambiguitas seperti itu berbahaya dalam teks hukum."],
    ["Which sentence suits formal legal-style analysis?","The provision is, on its plain meaning, incapable of supporting the respondent's interpretation.",["The respondent's reading of the provision is just plain silly, to be perfectly honest with all of you.","The provision, like, doesn't really say what the respondent thinks it says.","It is my feeling that the provision maybe means something a bit different."],"Kalimat ini formal, tegas, dan memakai istilah analisis hukum seperti 'plain meaning'."],
    ["Which revision is most concise? 'In the event that the party of the first part (the buyer) fails to make payment, the agreement may be terminated.'","If the buyer fails to pay, the agreement may be terminated.",["Non-payment: terminate.","In the event that the buyer fails to make payment, termination may occur.","If failure to make payment occurs, the agreement may then be terminated."],"Revisi ini mengganti frasa bertele-tele dengan 'if' dan verba langsung tanpa mengubah akibat hukumnya."],
    ["Which sentence best introduces the respondent's strongest argument?","The respondent's most substantial argument is that the user's continued use amounted to acceptance.",["The respondent also says some other things, which are listed below.","However, the respondent is obviously wrong about absolutely everything.","Next, I will talk about what the respondent said about the case."],"Analisis yang kuat menghadapi argumen lawan yang paling substansial, bukan yang paling lemah."],
    ["Which sentence best supports a legal conclusion with a policy rationale?","Requiring separate consent for each purpose preserves the user's control, the very interest the statute protects.",["Separate consent is nice because users generally like being asked about things.","Policy is very important in law, as all lawyers know from their training.","The statute exists, and therefore it must be obeyed by everyone."],"Kalimat ini mengaitkan tafsiran dengan tujuan undang-undang, yaitu perlindungan kendali pengguna."],
    ["Why should a legal-style analysis define 'personal data' at the outset?","Because whether the obligations apply at all depends on the scope of that term",["Because definitions make an analysis appear longer and more thorough to examiners","Because readers dislike any technical terms that are not explained","Because every paragraph in an analysis must begin with a definition"],"Penerapan kewajiban privasi bergantung pada apakah informasi tergolong 'personal data'."],
    ["Which sentence rebuts an opposing legal argument most effectively?","That reading would render Article 7(3) redundant, and statutes are not construed so as to deprive provisions of effect.",["That reading is simply wrong, because we disagree with it very strongly indeed.","That reading has been suggested, but there are other readings available too.","That reading is popular with companies, which in itself is rather suspicious."],"Bantahan ini memakai prinsip penafsiran undang-undang yang sah, bukan sekadar ketidaksetujuan."],
    ["Which concluding sentence best suits a legal-style analysis?","On balance, the clause is likely to be unenforceable, and the provider should obtain fresh, specific consent.",["In conclusion, the law is complicated, and lawyers often disagree about it.","The provider is a bad company and should therefore be punished severely.","This case shows that privacy is very important in the digital age."],"Kesimpulan ini memberi jawaban atas isu dengan tingkat kepastian yang tepat dan saran praktis."],
  ],
  14: [
    ["Which thesis best suits a cultural criticism essay on cultural memory and representation?","The new heritage museum remembers the colonial port vividly but selectively, staging its commerce while muting its labour.",["The heritage museum is a very interesting place that a great many local people and tourists visit.","Museums are boring places, and nobody should waste their precious free time wandering around them.","This essay will discuss memory and representation in culture, with reference to a number of different examples from several countries."],"Tesis kritik budaya ini membuat tafsiran tajam tentang apa yang ditonjolkan dan disembunyikan."],
    ["The model text advises moving 'beyond assertion'. In cultural criticism, which sentence does this best?","The film's soft-focus flashbacks invite nostalgia, and in doing so they quietly exempt the past from judgement.",["The film is nostalgic, which is obvious to anyone who has watched it carefully.","The film has several flashbacks, and they are all shown in soft focus.","Nostalgia is a feeling that many people experience at some point in life."],"Kalimat ini menjelaskan bagaimana teknik film menghasilkan efek makna, sehingga melampaui sekadar pernyataan."],
    ["Which item from the lesson's evaluation vocabulary best describes the claim that a single television series 'defined a generation'?","overstated",["consequential","defensible","methodologically weak"],"Klaim bahwa satu serial 'mendefinisikan satu generasi' biasanya berlebihan, sehingga 'overstated' paling tepat."],
    ["Which sentence offers the most precise close reading?","The poster places the farmer below the horizon line, so that the promised harvest literally looms over him.",["The poster is very colourful and shows a farmer standing in a large field.","The poster is a powerful image that really makes people stop and think.","The farmer in the poster is probably a symbol of something important."],"Pembacaan dekat yang baik menghubungkan detail visual spesifik dengan makna."],
    ["Spot the main weakness: 'Dangdut is simply the music of the working class.'","It reduces a complex, contested genre to a single social meaning",["It is too hedged to count as a critical claim","It fails to name a specific dangdut singer","It uses the present simple tense for what is presented as a general truth"],"Kritik budaya yang matang menghindari reduksi genre yang kompleks ke satu makna sosial."],
    ["Which sentence best situates a cultural artefact in its context?","Released months after the 1998 reforms, the album's ironic patriotism reads as a test of how much could now be said.",["The album was released in 1998 and contains twelve songs of varying length.","The album is patriotic and also ironic at the very same time.","Everyone loved the album when it came out, and it sold many copies."],"Kalimat ini menafsirkan karya melalui konteks sejarahnya, bukan hanya menyebut tanggal."],
    ["Which sentence uses a critical concept without jargon overload?","In Barthes's sense, the advert turns a historical choice into something that looks natural.",["The advert's hegemonic signification interpellates subjectivities via neoliberal semiotic matrices.","Barthes is a famous French theorist who wrote about a great many things.","The advert is natural, as Barthes himself would definitely have agreed."],"Konsep teoretis dipakai secara jelas untuk menjelaskan karya, tanpa jargon yang menutupi makna."],
    ["Which sentence offers the most nuanced judgement of a commemorative statue?","The statue honours the victims with dignity, yet its anonymity risks turning particular deaths into abstract sacrifice.",["The statue is beautiful, and therefore the commemoration is a complete success.","The statue is ugly, and it insults absolutely everyone who sees it.","The statue is made of bronze and stands in the middle of the main square."],"Penilaian ini mengakui kekuatan karya sekaligus risiko maknanya, sehingga bernuansa."],
    ["Which interpretation is most appropriately tentative?","The repeated empty chairs may be read as an image of the disappeared, though the director has never confirmed this.",["The empty chairs definitely represent the disappeared, exactly as the director clearly intended them to from the start.","The empty chairs mean nothing at all, since chairs in a film are just chairs.","There are many chairs in the film, and quite a few of them are empty."],"Tafsiran ini ditawarkan sebagai kemungkinan yang beralasan, bukan kepastian."],
    ["Which sentence suits a cultural criticism essay for an educated magazine readership?","What the festival sells as authenticity is, on closer inspection, a carefully curated version of the village.",["The festival is fake, lol, and the village is really not like that at all.","Authenticity has been problematised by numerous scholars (see Appendix B for details).","The festival is held every year in August and usually lasts for four days."],"Register ini tajam dan cerdas namun tetap mudah dibaca oleh pembaca majalah terpelajar."],
    ["Which revision is most concise? 'The series, in the way that it represents history, tends to have a tendency to romanticise the past.'","The series tends to romanticise the past.",["It romanticises.","In its representation of history, the series has a tendency to romanticise.","The series, in representing history, tends to have a romanticising tendency."],"'Tends to have a tendency' redundan, dan revisi ini mempertahankan klaim dengan kata paling sedikit."],
    ["Which sentence best anticipates a reader's objection to the critique?","One might object that entertainment owes history no accuracy; but the series markets itself precisely as history.",["Some readers will disagree, but they have simply not understood the series.","Objections are always possible in cultural criticism of any kind.","The series is just entertainment, so my critique may well be wrong."],"Kalimat ini menyajikan keberatan yang masuk akal lalu menjawabnya dengan fakta tentang karya."],
    ["Choose the most precise verb: 'The exhibition ___ the role of women in the independence struggle, mentioning them in only a single caption.'","marginalises",["commemorates","foregrounds","exaggerates"],"Menyebut perempuan hanya dalam satu keterangan berarti meminggirkan (marginalises) peran mereka."],
    ["Which sentence best analyses who is given a voice in a documentary?","Officials speak to camera at length; fishermen appear only in voice-over, their words paraphrased by the narrator.",["The documentary includes many interviews with a wide range of different people.","The fishermen are nice people, and the officials are not very nice people.","The documentary is about fishermen and their dealings with the government."],"Kalimat ini menganalisis representasi melalui siapa yang berbicara langsung dan siapa yang diwakili."],
    ["Which closing sentence best suits a cultural criticism essay?","To remember the port differently would require not new monuments but a willingness to let the old ones be questioned.",["In conclusion, culture and memory are both very important topics for everyone.","I recommend visiting the museum if you happen to have a free afternoon.","Memory is complex, and this essay has discussed some aspects of it."],"Penutup ini menyintesis kritik menjadi implikasi yang tajam dan reflektif."],
  ],
  15: [
    ["Which opening best suits an email addressing a sensitive workplace conflict with a colleague?","I wanted to follow up on Tuesday's meeting, as I think we would both benefit from talking through what happened.",["We need to talk about your terrible behaviour at Tuesday's meeting, and we need to do it immediately, this afternoon.","Hi! Hope you're well! Just a quick note about nothing much, really, so don't worry about it!","This email concerns an incident which occurred recently and which was, in many respects, regrettable."],"Pembuka ini menyebut konteks secara netral dan mengajak dialog tanpa menyalahkan."],
    ["The model text values writing that is 'formal but not inflated'. Which sentence fits a sensitive email to a colleague?","I recognise that the deadline change put you in a difficult position, and I should have flagged it sooner.",["I am most profoundly and eternally regretful for the grievous matter of the deadline.","Sorry about the deadline thing, my bad, won't happen again lol.","The deadline was changed, as deadlines sometimes are in this organisation."],"Kalimat ini sopan, tulus, dan lugas tanpa bahasa yang berlebihan atau terlalu santai."],
    ["The writing task asks for a concession. In an email responding to a colleague's complaint about you, which concession is most constructive?","You are right that I took the client call without you; I'd like to explain why and agree how we handle such calls.",["You may be right, but frankly you are overreacting a great deal about this whole thing.","I concede nothing, as I have done absolutely nothing wrong in this situation.","Concessions are not appropriate in professional emails, so I will not make one."],"Konsesi ini mengakui fakta, memberi penjelasan, dan mengusulkan solusi ke depan."],
    ["Which sentence describes a team conflict neutrally to a line manager?","Ani and Budi disagree about who owns the vendor relationship, and the uncertainty has delayed two orders.",["Budi has been rude and aggressive to poor Ani for weeks now, and it is getting worse.","There is drama in the team, and people are getting very upset about it.","Something happened between two people, which I would prefer not to specify."],"Deskripsi netral menyebut inti perselisihan dan dampaknya tanpa memihak."],
    ["Which sentence sets a boundary firmly but courteously?","I am happy to discuss the budget, but I won't be able to respond to messages sent after 9 p.m.",["Stop messaging me at night, because it is really annoying and extremely unprofessional of you.","If it's not too much trouble, maybe you could perhaps not message so late?","I will no longer be reading any of your messages from now on."],"Kalimat ini jelas tentang batas sekaligus menunjukkan kesediaan bekerja sama."],
    ["Spot the weakness: 'Per my last email, which you clearly did not read, the figures are attached again.'","Its passive-aggressive tone is likely to escalate the conflict",["It is far too long for a professional email","It does not actually include the figures as an attachment to the email","It uses the word 'per' incorrectly"],"Sindiran 'which you clearly did not read' bernada pasif-agresif dan memperburuk konflik."],
    ["Which subject line suits an email proposing mediation between team members?","Proposal: facilitated conversation about project roles",["URGENT!!! Problem with Budi","Hi","Some thoughts I had over the weekend about things at work"],"Subjek ini informatif dan netral, tanpa menyalahkan siapa pun atau terlalu kabur."],
    ["Which sentence escalates an unresolved issue to HR most appropriately?","Despite two meetings, we have not reached agreement, so I would welcome HR's guidance on next steps.",["I am reporting Budi to HR because he refuses to listen to anyone at all.","HR needs to fix this mess right now, because I am completely done with it.","I am not sure whether to involve HR, so I am copying everyone in instead."],"Eskalasi yang profesional menyebut upaya yang sudah dilakukan dan meminta bimbingan secara netral."],
    ["A colleague has complained about you and copied in the whole team. What is the best approach?","Reply privately, keeping the discussion between the people directly involved",["Reply to all, so that everyone in the team can see your side of the story","Forward the complaint to your manager without any comment","Ignore the email until the colleague apologises to you"],"Membalas secara pribadi mencegah konflik meluas dan menjaga martabat kedua pihak."],
    ["Which sentence makes a diplomatic request to a senior colleague who contradicted you publicly in a meeting?","Would you be open to raising concerns about my figures with me before the meeting next time?",["Never contradict me in a meeting again, please, as it is unprofessional.","I would like it if you would maybe sometimes think about possibly talking to me first at some point.","You undermined me in front of everyone, and I demand an explanation."],"Permintaan ini sopan, spesifik, dan berorientasi solusi, sesuai dengan hubungan kepada atasan."],
    ["Which sentence acknowledges a colleague's feelings without accepting blame for something you did not do?","I can see the decision felt unfair to you, and I'd like to explain how it was reached.",["I am so sorry that I made such a terrible and unfair decision about this whole matter last week.","Your feelings are your own problem, not mine, so I cannot help you.","If you feel that way, then that is unfortunate for you, I suppose."],"Kalimat ini berempati pada perasaan rekan sambil menawarkan penjelasan, bukan pengakuan salah."],
    ["Which revision is most concise? 'I am writing this email to you in order to let you know that the meeting has been moved.'","The meeting has been moved.",["I am writing to let you know that the meeting has moved.","This email is to let you know that the meeting has been moved.","In order to let you know, the meeting has now been moved."],"Pesan intinya hanya bahwa rapat dipindah, sehingga frasa pembuka tentang menulis email dapat dihapus."],
    ["Which closing line best ends an email after a difficult conversation?","I'll send a summary of what we agreed by Friday; please let me know if I've missed anything.",["Anyway, let's just never speak about any of this ever again.","Hope this is the end of it, thanks very much.","Please do not hesitate to contact me about anything whatsoever."],"Penutup ini menetapkan tindak lanjut yang jelas dan membuka ruang koreksi."],
    ["Writing to a senior counterpart at a partner organisation about a missed deliverable, which sentence balances directness and respect?","We have not yet received the revised schedule; could we agree on a date that works for your team?",["You have missed the deliverable, which is completely unacceptable to us.","It is no problem at all if the revised schedule never arrives.","Perhaps, if possible, at some point, a schedule may possibly be sent."],"Kalimat ini menyatakan fakta secara jelas dan mengajukan solusi dengan sopan."],
    ["Which sentence keeps facts separate from interpretation?","The report was submitted on 12 May, three days after the agreed date; I may be missing context about the delay.",["The report was late again, as usual, because of yet more carelessness.","The report was submitted at some point, which is perfectly fine.","The report was obviously sabotaged by someone in the team."],"Kalimat ini menyebut fakta yang dapat diverifikasi dan membuka kemungkinan penjelasan lain."],
  ],
  16: [
    ["Which opening line best suits a formal speech on educational reform?","Twenty years ago, a child here needed luck to finish school; today she needs only to turn up. Let us finish that job.",["Good evening. Today I am going to talk to you about education reform for about twenty minutes or so, if that's all right.","Education is the most important thing in the whole entire world, and everybody here knows it.","According to Table 4 of the 2025 report, completion rates rose by 3.2 percentage points overall."],"Pembuka pidato ini memakai kontras yang mudah diingat dan langsung menyatakan tujuan bersama."],
    ["The model text says a conclusion should explain what the audience 'should now understand differently'. In a speech, this is best achieved by:","a closing image or line that reframes the reform's purpose for the audience",["a slide that repeats every statistic mentioned earlier in the speech, one by one","thanking the audience and leaving without any final point","introducing a new policy that has not been discussed so far"],"Penutup pidato yang efektif membingkai ulang makna reformasi dengan kalimat yang membekas."],
    ["The lesson stresses 'reader impact'. Which adjustment best adapts this principle for a listening audience?","Using signposts and deliberate repetition, since listeners cannot reread",["Adding footnotes so that listeners can check the sources","Using longer embedded clauses to sound more formal","Removing all pauses to keep the speech as short and fast as possible overall"],"Pendengar tidak bisa membaca ulang, sehingga penanda arah dan pengulangan yang disengaja sangat membantu."],
    ["Which sentence uses a three-part structure most effectively in a speech?","We built the schools; we trained the teachers; now we must trust them.",["We built the schools and trained the teachers and did lots of other things.","Schools, teachers, and various other things are all very important.","We built, trained, and trusted schools, teachers, and them as well."],"Pola tiga bagian yang paralel dan memuncak pada bagian ketiga membuat pesan kuat dan mudah diingat."],
    ["Which version is better suited to being spoken aloud?","Here is the problem. Half our teachers will retire within ten years. Who will replace them?",["The problem, which is that half of our teachers, many of whom are senior, will retire within ten years, raises the question of replacement.","Retirement-driven teacher-supply discontinuities constitute a significant medium-term systemic risk.","Please see the attached table for teacher retirement projections broken down by province."],"Kalimat pendek dan pertanyaan langsung lebih mudah dipahami pendengar daripada kalimat panjang bertingkat."],
    ["Which sentence best signposts a speech for listeners?","I want to make three points tonight, and the third is the one I hope you will remember.",["As shown in section 2.3 above, the following points are relevant to the discussion this evening.","There are some points which I will now proceed to enumerate one by one.","Points will be made tonight, and they will be made in some kind of order."],"Penanda ini memberi struktur yang jelas dan sekaligus menarik perhatian pendengar."],
    ["Addressing parents at a town-hall meeting, which sentence strikes the right register?","Many of you have told me your children feel tested more than taught. You are right, and that is what we will change.",["Pursuant to Ministerial Regulation 14/2025, the frequency of assessment shall be revised accordingly with immediate effect.","Parents, just chill out, honestly the tests really aren't that big of a deal for the kids.","The pedagogical literature has long problematised high-stakes assessment paradigms in schools."],"Register ini formal namun hangat, langsung menyapa kekhawatiran orang tua dengan bahasa yang jelas."],
    ["Spot the main weakness in this speech line: 'In 2019, 43.7% of schools, as opposed to 38.2% in 2016 and 41.9% in 2018, reported shortages.'","It packs too many precise figures into one sentence for listeners to retain",["It uses the simple past tense to report statistical data about previous years","It is too emotional for a formal public address","It does not name any of the schools concerned"],"Pendengar sulit menangkap banyak angka sekaligus, sehingga pidato sebaiknya memilih satu angka kunci."],
    ["Which anecdote best serves a speech on vocational education?","Last month I met Sari, who left school at fifteen and now trains apprentices in the workshop where she once swept floors.",["I once went on holiday abroad and saw a lot of very interesting buildings and a few old factories.","Some people go to vocational schools, and some people do not go to vocational schools at all.","There is a story about a student that I wanted to tell, but it is a bit too long for tonight."],"Anekdot ini spesifik, manusiawi, dan langsung mendukung pesan tentang nilai pendidikan vokasi."],
    ["Which rhetorical question is most effective in a speech supporting teacher pay reform?","If we trust teachers with our children, why do we not trust them with a living wage?",["Do you know what the word 'teacher' originally meant in ancient Latin or perhaps in Greek?","Isn't it true that teachers are, like, important or whatever, really?","What percentage increase in pay did the 2023 review actually recommend?"],"Pertanyaan retoris ini memakai paralelisme 'trust' untuk menyoroti ketidakadilan secara kuat."],
    ["Which concession works best with an audience sceptical of reform?","I know reform has been promised before and has not always arrived. So tonight, let me tell you exactly what will be different.",["Some of you here tonight are sceptical about reform, but I am afraid you are simply wrong about it.","Reform is very difficult, and to be perfectly honest, it may well fail again this time too.","Scepticism is a philosophical position with a long and distinguished history in Western thought."],"Konsesi ini mengakui kekecewaan audiens lalu langsung beralih ke komitmen yang konkret."],
    ["Which revision makes this line more effective for delivery? 'It is the case that there are still many children who are not able to access schools.'","Too many children still cannot get to school.",["Access remains an issue.","It is still the case that many children cannot access schools.","Children who are not able to access schools still exist in many cases."],"Versi ini ringkas, tegas, dan mudah diucapkan sehingga lebih kuat untuk pidato."],
    ["Why might a speechwriter place a key statistic in a sentence of its own?","To create a pause that gives the figure emphasis and time to register",["Because statistics must always be separated from other sentences in a script","To make the script look longer and more substantial on the page","Because listeners prefer to hear numbers delivered very quickly"],"Kalimat tersendiri menciptakan jeda sehingga angka penting lebih ditekankan dan diingat."],
    ["Which line uses 'we' most effectively to build shared responsibility?","This is not the government's reform or the teachers' reform; it is ours, and we will be judged by it.",["We, the government, have decided this, and all of you will simply have to accept it without complaint.","We think that you should think about reform, and we hope that you will.","We will see whether reform happens, and in the meantime we will wait."],"'We' di sini menyatukan semua pihak sebagai pemilik reformasi dan menekankan tanggung jawab bersama."],
    ["Which closing line best ends a speech on educational reform?","Let us measure this reform not by the buildings we open, but by the doors they open for our children.",["Thank you. That is the end of my speech. Are there any questions from the floor?","In conclusion, I have talked about three different things here tonight.","Education reform is complex, and there is much more that could be said."],"Penutup ini memakai permainan kata yang bermakna untuk membingkai ulang tujuan reformasi."],
  ],
  17: [
    ["Which opening best suits a sophisticated review of a film that divides audiences?","Few films this year have been booed and wept over in equal measure, and both responses, oddly, are earned.",["This film is about a family who decide to move from the city to the countryside.","Everyone should see this film, because it is quite simply the best film ever made.","Some people liked the film when it came out, and some people did not like it."],"Pembuka ini mengakui perpecahan penonton dan langsung menawarkan sudut pandang kritis yang menarik."],
    ["The model text advises acknowledging 'a plausible objection'. In a review of a divisive novel, which sentence does this best?","Readers who find the narrator insufferable are not misreading the book; they are responding to exactly what it does to them.",["Readers who dislike the narrator simply do not understand literature or how novels actually work.","The narrator is insufferable from start to finish, and so the novel is a bad novel overall.","Some readers dislike the narrator, but personally I liked her quite a lot, so that is fine."],"Kalimat ini menghormati keberatan pembaca dan menjadikannya bagian dari analisis."],
    ["Which item from the lesson's evaluation vocabulary best fits a subplot that is introduced but never pursued?","underdeveloped",["overstated","defensible","consequential"],"Subplot yang diperkenalkan tetapi tidak dikembangkan paling tepat disebut 'underdeveloped'."],
    ["Which sentence best supports an evaluation with specific detail?","The score withholds its main theme until the final reel, so the resolution sounds earned rather than announced.",["The music in the film is really good and fits the story very well throughout.","The music was composed by a famous and highly respected composer from Japan.","The score is one of the many different elements that make up the film."],"Evaluasi ini didukung detail spesifik dan menjelaskan efeknya pada pengalaman penonton."],
    ["Which sentence gives readers enough plot to follow the critique without overloading them?","A widowed ferry pilot agrees to carry one last passenger, and the crossing becomes a reckoning neither expected.",["First the pilot wakes up, then he eats breakfast, then he goes to the port, and then he meets a man at the ticket gate.","The plot is very complicated and really quite hard to summarise in a short review like this.","The film has a plot, which unfolds over a period of just over two hours."],"Ringkasan ini singkat namun cukup memberi konteks dan menarik tanpa membocorkan cerita."],
    ["Which sentence delivers a mixed verdict with precision?","The novel's first half is a masterclass in withheld information; its second half explains far more than it needs to.",["The novel is good and bad, depending on which part of it you happen to be reading.","The novel is excellent overall, with no real weaknesses of any kind worth mentioning.","The novel has two halves of roughly equal length, with a short epilogue at the end."],"Penilaian ini menyebut kekuatan dan kelemahan secara spesifik pada bagian yang berbeda."],
    ["Spot the main weakness: 'The director's intention was clearly to criticise capitalism, so the film succeeds.'","It equates presumed intention with artistic success",["It uses an adverb that is too informal for a review","It is too long to work as an opening sentence","It fails to mention the film's running time"],"Niat sutradara, apalagi yang hanya diduga, tidak otomatis membuat karya berhasil secara artistik."],
    ["Which sentence best situates a novel within its author's body of work?","Where her earlier novels resolved their mysteries, this one leaves the central disappearance unexplained, and is braver for it.",["She has written several novels over the years, and this is the newest one she has published.","This novel is far better than all of her other novels put together, without any question.","She wrote her first novel back in 2009, when she was about thirty years old."],"Kalimat ini membandingkan karya baru dengan karya sebelumnya dan memberi penilaian berdasarkan perbedaan itu."],
    ["Choose the most precise word: 'The film's pacing is deliberately ___, lingering on silences that some viewers will find unbearable.'","unhurried",["frenetic","inconsistent","abrupt"],"Kata 'lingering on silences' menunjukkan tempo lambat yang disengaja, sehingga 'unhurried' paling tepat."],
    ["Which sentence best advises readers without condescending to them?","Those who need a plot to drive a film will be frustrated; those willing to sit with an image will find much to admire.",["Anyone who does not appreciate this film is clearly not intelligent enough to understand it.","Absolutely anyone will enjoy this film very much, whatever their taste in cinema may be.","Watch it or don't watch it; honestly, it is entirely up to you what you decide to do."],"Saran ini membantu pembaca menilai kecocokan film dengan selera mereka tanpa merendahkan."],
    ["Which interpretation is offered with appropriate tentativeness?","The final shot can be read as forgiveness, though its ambiguity seems deliberate.",["The final shot means forgiveness, and it cannot possibly mean anything else at all.","The final shot is confusing, so it has no real meaning at all.","The final shot lasts for exactly forty seconds without a cut."],"Tafsiran ini ditawarkan sebagai kemungkinan dan mengakui ambiguitas yang disengaja."],
    ["Which revision is most concise? 'The acting performances given by the actors in the film are, generally speaking, on the whole, strong.'","The performances are generally strong.",["Strong acting.","The acting performances by the actors are generally strong.","On the whole, generally, the performances given are strong."],"Revisi ini menghapus redundansi 'acting performances by the actors' dan 'generally/on the whole'."],
    ["Which sentence praises a debut novel without hyperbole?","It is a debut of unusual control, though its final chapter strains for an effect the rest achieves quietly.",["This is quite simply the greatest debut novel in the entire history of literature.","This debut is a must-read masterpiece for absolutely everyone, young and old.","This debut is a book that has been written by an author who is new."],"Pujian ini spesifik dan seimbang dengan kritik kecil, sehingga lebih kredibel."],
    ["Which sentence best links a formal choice to meaning?","The fractured timeline mirrors the narrator's unreliable memory, so the reader experiences confusion rather than being told of it.",["The timeline is fractured, which is a technique that has become very popular in recent novels.","The narrator has a bad memory, and also the timeline of the novel is fractured.","The timeline jumps from 1965 to 1998 and then back again to the 1970s."],"Kalimat ini menjelaskan bagaimana pilihan bentuk menghasilkan makna dan efek bagi pembaca."],
    ["Which closing sentence best ends a review of a divisive film?","You may leave the cinema irritated, but you are unlikely to leave it unchanged.",["In conclusion, the film is good, and I would recommend it to others who like dramas.","I give this film three and a half stars out of a possible five.","The film is showing in cinemas across the country from Friday."],"Penutup ini merangkum sifat film yang memecah penonton dalam kalimat yang tajam dan berkesan."],
  ],
  18: [
    ["Which opening best suits a literary nonfiction piece about a personal encounter with social change?","The morning the market became a car park, my grandmother still walked there, purse in hand, as if the stalls might return.",["Social change is a complex process that affects many different societies in many different ways over long and uneven periods of time.","This essay will describe the various ways in which my home town changed between the years 1995 and 2020.","Change is everywhere in the modern world, and it can be either good or bad depending on the situation."],"Pembuka ini memakai adegan konkret yang memuat perubahan sosial melalui pengalaman pribadi."],
    ["The model text warns against sounding impressive 'at the expense of clarity'. In narrative nonfiction, which sentence best heeds this?","The river had been rerouted, and with it went the reason the village existed.",["The cerulean, sinuous, effulgent river, in its ineffable majesty, was rerouted.","The river got moved somewhere else, which was a really big change for us.","Rerouting of the river occurred, with a range of consequences for the village."],"Kalimat ini sederhana namun bermakna dalam, menghindari diksi berlebihan maupun kesan datar."],
    ["The writing task asks for a 'synthesising conclusion'. In narrative nonfiction, this is best achieved by:","an ending image that gathers the personal story into its wider meaning",["a bullet-point list of all the practical lessons that the writer learned","an abrupt stop without any reflection on what happened","a summary of national statistics about social change"],"Dalam nonfiksi naratif, sintesis biasanya dicapai lewat gambaran penutup yang merangkum makna cerita."],
    ["Which sentence shows rather than tells the family's poverty?","We ate rice with salt on the days before payday and pretended, for my sister's sake, that it was a game.",["We were very poor at that time, and life was extremely hard for every one of us.","Poverty affected our family in a great many negative ways over those years.","Our family had a relatively low household income during that particular period."],"Detail konkret tentang nasi dan garam menunjukkan kemiskinan tanpa menyebutnya secara langsung."],
    ["Which detail most effectively anchors a scene in a specific time and place?","The radio on the windowsill was still tuned to RRI, crackling through the 1997 election results.",["It was a long time ago, in a place that was very far away from here.","The room had some furniture in it and a few other things as well.","It was evening, and the weather was fairly normal for that time of year."],"Detail spesifik seperti stasiun radio dan peristiwa nyata menempatkan adegan pada waktu dan tempat yang jelas."],
    ["What ethical obligation most distinguishes narrative nonfiction from fiction?","The writer must not invent events or composite characters without telling the reader",["The writer must avoid using dialogue anywhere in the piece","The writer must use the third person throughout the text","The writer must present every event in chronological order"],"Nonfiksi naratif terikat pada kebenaran faktual, sehingga rekaan harus diungkapkan kepada pembaca."],
    ["Which sentence best blends the younger self's perception with the older narrator's understanding?","I thought the new road was a gift; I did not yet know what it would carry away.",["I thought the road was nice back then, and I still think it is quite nice today.","The road was built in 2003 by a large national construction company.","Roads are often built in order to connect villages to the nearest cities."],"Kalimat ini memadukan pandangan masa kecil dengan kesadaran narator dewasa melalui ironi yang halus."],
    ["Spot the main weakness: 'It was a dark and stormy night, and my heart was pounding like a drum.'","It relies on stock phrases instead of observed, particular detail",["It uses the past tense for the narration","It contains too much statistical information","It is written in the first person singular"],"Frasa klise seperti 'dark and stormy night' melemahkan tulisan yang seharusnya berbasis detail nyata."],
    ["Which line of reported dialogue reveals character most economically?","'Land doesn't argue,' my father said, signing the papers without reading them.",["My father said many different things about the land, and then he signed the papers.","'I am feeling very sad about signing these papers,' my father said, sadly.","My father talked for a while, and after that he signed some papers."],"Dialog singkat dan tindakan tanpa membaca dokumen mengungkap watak sang ayah secara efisien."],
    ["Which revision best quickens the pace of an action moment? Original: 'The water then began, slowly at first but gradually increasing, to rise up over the doorstep.'","The water reached the doorstep. Then it crossed it.",["The water, which had been rising slowly, gradually rose over the doorstep.","Gradually, slowly, the water rose up and over the step.","The water began rising over the doorstep gradually, at first slowly."],"Kalimat pendek berturut-turut mempercepat tempo dan menciptakan ketegangan."],
    ["Which sentence best connects a personal moment to broader social change?","Ours was one of 4,000 households moved that year, though at the time it felt as if the world had chosen only us.",["My family moved house that year, which was a very big event in my life at the time.","Many households are moved every year in many countries for many different reasons.","We moved house, and statistics about moving house are actually quite interesting."],"Kalimat ini menghubungkan pengalaman pribadi dengan skala sosial sambil mempertahankan perasaan subjektif."],
    ["Which ending is most effective for a piece about a demolished cinema?","Now there is a pharmacy where the screen was. I still lower my voice when I walk past.",["In conclusion, demolishing old cinemas is wrong and should simply be banned by national law.","And that is the story of the cinema, which I hope you have enjoyed reading.","Cinemas are important cultural spaces in every community around the world."],"Penutup yang menahan diri ini menyampaikan kehilangan melalui gambaran konkret, bukan pernyataan langsung."],
    ["Which revision is most concise without losing the image? 'The old man, who was elderly, sat in silence without speaking on the bench.'","The old man sat silently on the bench.",["He sat.","The elderly old man sat on the bench in silence.","The old man, who was old, sat without speaking."],"Revisi ini menghapus redundansi 'old/elderly' dan 'in silence/without speaking' sambil mempertahankan gambaran."],
    ["Which use of the present tense is most purposeful in a past-tense memoir?","Even now, the smell of diesel takes me back to the ferry that carried us away.",["Yesterday I go to the market and buy some fish for dinner.","In 1999 we move to Surabaya and live there for many years.","The ferry is leaving in 2001 when we are on it with all of our bags and boxes."],"Present tense di sini menandai pengalaman yang masih terasa saat ini, sehingga perpindahan kala bermakna."],
    ["Which sentence acknowledges the limits of the narrator's perspective?","I can tell this only from my side of the fence; the neighbours who stayed would tell it differently.",["Everyone in the village felt exactly the same way that I did about it.","My perspective is the only true one, because I was actually there.","Perspective is a topic that is often discussed in philosophy and literature."],"Narator yang jujur mengakui bahwa pengalamannya hanyalah satu sudut pandang."],
  ],
  19: [
    ["Three sources on environmental responsibility blame consumers, corporations, and governments respectively. Which thesis synthesises them best?","The sources disagree about who bears responsibility, but all three assume it can be assigned to a single actor, an assumption worth questioning.",["Source A blames consumers, Source B blames corporations, and Source C blames governments for environmental damage.","All three sources are correct, so in the end everyone is responsible for absolutely everything that happens.","Source B is the best source, because corporations are obviously the main polluters in the modern world."],"Tesis sintesis ini menemukan asumsi bersama yang tersembunyi di balik perbedaan sumber."],
    ["The model text says a stronger text 'synthesises the argument'. In a multi-source synthesis, the conclusion should mainly:","state what the sources reveal together that none reveals alone",["summarise each source again in the order in which they were presented","choose the most famous author and endorse their view","list further sources the writer did not have time to read"],"Kesimpulan sintesis menunjukkan wawasan baru yang muncul dari gabungan sumber."],
    ["Which phrase from the lesson's synthesis tools best introduces an integrated judgement across sources?","Taken together, these considerations suggest",["It would be premature to conclude","More specifically","In practical terms"],"'Taken together' menandai penilaian yang menggabungkan beberapa sumber, sesuai fungsi sintesis."],
    ["Which sentence most precisely shows that one source extends another?","Where Lim documents the decline in urban bee populations, Osei traces it to a specific class of pesticides.",["Lim writes about bees in cities. Osei also writes about bees in cities.","Lim and Osei both agree completely about everything to do with bees.","Osei strongly disagrees with all of Lim's earlier research on urban bees."],"Kalimat ini menunjukkan bahwa Osei melanjutkan temuan Lim dengan menjelaskan penyebabnya."],
    ["Which sentence weighs sources by quality rather than number?","Although four blog posts dispute the finding, the single peer-reviewed meta-analysis carries more evidential weight.",["Four separate sources dispute the finding, so the finding is probably wrong.","All sources are equally valid, regardless of where or how they appear.","The meta-analysis is longer than the blog posts, so it must be more reliable."],"Bobot bukti ditentukan oleh kualitas metode, bukan jumlah sumber."],
    ["Original: 'Coastal mangroves sequester carbon at rates up to four times those of tropical forests.' Which version is an acceptable paraphrase?","Per hectare, mangroves can store up to four times as much carbon as tropical rainforests (Ali, 2022).",["Coastal mangroves sequester carbon at rates up to four times those of tropical forests (Ali, 2022).","Coastal mangroves capture carbon at rates up to four times those of tropical forests.","Mangroves are very important for the environment, as Ali has said."],"Parafrase yang sah mengubah struktur dan kata, mempertahankan makna, dan mencantumkan sumber."],
    ["Choose the reporting verb that best signals the writer's scepticism: 'The industry report ___ that recycling targets are already being met.'","insists",["demonstrates","establishes","shows"],"'Insists' menyiratkan klaim yang dipertahankan tanpa bukti kuat, sedangkan pilihan lain menunjukkan penerimaan."],
    ["Spot the weakness: 'As Ramos (2020) proves, carbon taxes are the only effective climate policy.'","It inflates a single source's claim into proven, exclusive fact",["It uses an in-text citation in the wrong format for the referencing style","It should use the present perfect 'has proved'","It is too tentative for an academic synthesis"],"Satu sumber tidak dapat 'membuktikan' klaim eksklusif, sehingga sintesis ini berlebihan."],
    ["Which sentence best handles sources that use different definitions?","Because Patel counts only industrial emissions while Moreau includes transport, their totals are not directly comparable.",["Patel and Moreau give different totals, so one of them must have made a mistake.","Patel's figure is higher, which proves the problem is worse than Moreau thinks.","Patel and Moreau both write about carbon emissions in Europe."],"Kalimat ini menjelaskan perbedaan angka melalui perbedaan definisi, bukan menganggap salah satu keliru."],
    ["Which sentence best shows the writer's own position emerging from the sources?","If, as all three sources concede, offsets are hard to verify, relying on them for net-zero targets seems imprudent.",["Source A, Source B, and Source C all talk about carbon offsets in some way.","I personally do not like offsets, whatever the sources may say about them.","The sources contain many different opinions about carbon offsets."],"Posisi penulis dibangun dari titik temu sumber, sehingga suaranya terintegrasi dengan bukti."],
    ["Which revision is most concise? 'In the article that was written by Silva, which was published in 2021, she argues that...'","Silva (2021) argues that...",["Silva argues...","In Silva's article, published in 2021, she argues that...","In the 2021 article written by Silva, it is argued that..."],"Sitasi integral 'Silva (2021) argues' memuat penulis, tahun, dan sikap dengan sangat ringkas."],
    ["Which paragraph plan best suits a synthesis of three sources on fast fashion?","Organise by issue (labour, waste, regulation), drawing on each source where relevant",["One paragraph per source, in the order in which the sources were originally found and read","One paragraph of quotations followed by a personal opinion","Organise by author nationality and then by date of publication"],"Sintesis disusun berdasarkan isu agar sumber saling dihubungkan, bukan diringkas satu per satu."],
    ["Which sentence integrates a quotation most smoothly?","Hassan's warning that 'efficiency gains are routinely consumed by increased demand' explains why the savings never materialised.",["'Efficiency gains are routinely consumed by increased demand.' This is a quotation from Hassan's book.","Hassan says a quote: 'efficiency gains are routinely consumed by increased demand', which is true.","There is a well-known quotation by Hassan about efficiency and demand in his work."],"Kutipan ini menyatu dalam kalimat penulis dan langsung dipakai untuk menjelaskan argumen."],
    ["Which synthesis claim is best calibrated?","The three studies converge on a modest effect, though their shared reliance on self-report limits confidence.",["The three studies prove a large effect beyond any possible doubt.","The three studies are different, so no conclusion is possible.","The three studies were all published at some point after 2018."],"Klaim ini menyebut kesamaan temuan sekaligus kelemahan metodologis bersama."],
    ["Two sources disagree on whether eco-labels change behaviour. Which sentence offers a plausible reconciliation?","The discrepancy may reflect context: labels seem effective for cheap groceries but not for expensive durable goods.",["One of the sources must have made a serious mistake in its calculations.","Both sources are right, so eco-labels both work and do not work at once.","The disagreement shows that research on eco-labels is simply useless."],"Rekonsiliasi ini menjelaskan perbedaan temuan melalui konteks yang berbeda."],
  ],
  20: [
    ["According to the model text, what should a polished text resist?","Sounding impressive at the expense of clarity",["Qualifying the overall scope of its central claim","Acknowledging a plausible objection","Synthesising rather than repeating"],"Kalimat pertama teks model menyatakan tulisan yang matang harus menolak godaan terdengar mengesankan dengan mengorbankan kejelasan."],
    ["The writing task asks for 350-450 words, but your portfolio piece has 520. Which cut best preserves quality?","Remove a second example that duplicates the first one's point",["Delete the concession, since it argues against your thesis","Cut the conclusion and let the final body paragraph end the text","Remove all qualification so that claims are stated more briefly"],"Contoh yang mengulang poin yang sama dapat dipangkas tanpa melemahkan argumen atau struktur wajib."],
    ["Which revision-checklist question addresses whether a portfolio essay's ending merely restates its opening?","Does the conclusion synthesise rather than repeat?",["Is the central claim exact and defensible?","Does each paragraph perform a clear function?","Have I qualified claims where evidence is limited?"],"Pertanyaan ini secara langsung memeriksa apakah kesimpulan menyintesis atau hanya mengulang."],
    ["A portfolio contains a report, an editorial, and a reflective essay on one theme. What are assessors most likely to look for?","Control of each genre's conventions, shaping the same material differently for each purpose",["Identical structure and tone across all three pieces, for the sake of overall consistency and unity","The highest possible number of rare and advanced words in each of the pieces","The longest possible piece that can be produced within each of the genres"],"Portofolio C2 menilai kemampuan menyesuaikan materi yang sama dengan konvensi tiap genre."],
    ["Spot the problem in this policy-report sentence: 'The ministry's plan is, quite frankly, a bit of a mess.'","Its conversational register is unsuitable for the genre",["It contains a subject-verb agreement error","It is too hedged to state a clear finding","It uses the possessive apostrophe in 'ministry's' incorrectly"],"'Quite frankly' dan 'a bit of a mess' terlalu santai untuk laporan kebijakan."],
    ["Which revision best improves cohesion? 'Inflation fell. The central bank raised rates. Borrowing slowed.'","The central bank raised rates; borrowing slowed, and inflation duly fell.",["Inflation fell, and the central bank raised rates, and borrowing slowed.","Inflation fell. Also, the central bank raised rates. Also, borrowing slowed.","Borrowing slowed. Inflation fell. The central bank raised rates."],"Revisi ini menata urutan sebab-akibat secara logis sehingga hubungan antarkalimat jelas."],
    ["Which revision of 'The new law had a big impact on lots of farmers' is most precise?","The new law cut subsidies for roughly 60% of smallholders.",["The new law had a significant impact on numerous farmers.","The new law impacted farmers in a big and important way.","The novel legislation exerted a colossal influence upon agriculturalists."],"Revisi ini mengganti 'big impact' dan 'lots of' dengan tindakan dan jumlah yang spesifik."],
    ["Which sentence shows the most calibrated stance in a portfolio essay on universal basic income?","The pilots suggest that basic income does not reduce work effort, although none has run long enough to test long-term effects.",["Basic income has been proven to work perfectly in every single pilot that has ever been carried out anywhere in the world so far.","Nothing at all can be concluded about basic income from any of the pilots that have been run so far.","Basic income pilots have been run in a number of countries, including Finland, Kenya, and elsewhere."],"Sikap ini menyatakan temuan dengan yakin sekaligus menyebut batas bukti yang nyata."],
    ["Which feedback note from a C2 assessor is most actionable?","Paragraph 3 asserts that housing costs drive migration but offers no evidence; add a source or qualify the claim.",["Good essay overall, but it could definitely be better in a number of places.","Your writing really needs a lot more C2-level vocabulary throughout the essay.","Some of the paragraphs are noticeably weaker than some of the others."],"Umpan balik ini menyebut lokasi, masalah, dan cara memperbaikinya secara spesifik."],
    ["In a portfolio essay, a paragraph lists three further examples of a point already established. What is the best revision?","Replace the list with one example that extends or complicates the argument",["Add a fourth example to make the point even stronger","Move the whole paragraph up into the introduction","Keep it but add more linking words between each of the three examples given"],"Paragraf C2 harus mengembangkan argumen, bukan menumpuk contoh untuk poin yang sudah terbukti."],
    ["Which sentence uses inversion correctly to emphasise the writer's criticism?","Rarely has a reform promised so much and specified so little.",["Rarely a reform has promised so much and specified so little.","A reform has rarely promised so much and specified so little.","Rarely, as a reform, it promised so much and specified so little."],"Setelah 'Rarely' di awal kalimat, inversi 'has a reform' wajib dan memberi penekanan."],
    ["Which revision cuts the most redundancy? 'Each and every individual student must personally submit their own portfolio by the deadline date.'","Each student must submit their portfolio by the deadline.",["Submit by the deadline.","Every individual student must submit their own portfolio by the deadline date.","Each and every student must personally submit a portfolio by the date."],"Revisi ini menghapus 'each and every', 'individual', 'personally', 'own', dan 'date' yang berlebihan."],
    ["Which title best suits a portfolio essay arguing that heritage tourism distorts local culture?","Staged for Visitors: How Heritage Tourism Rewrites Local Culture",["Tourism and Culture","An Essay About Heritage Tourism and Some of Its Effects on People","Tourism Is Bad for Culture!!!"],"Judul ini menarik dan sekaligus menyampaikan argumen utama esai secara tepat."],
    ["In the final ten minutes of a timed C2 assessment, which check is most valuable?","Verifying that the thesis and conclusion still match the argument actually written",["Replacing simple words with longer and rarer synonyms throughout the whole of the text","Counting every word precisely to report the exact total","Rewriting the introduction in a completely different style"],"Argumen sering bergeser saat menulis, sehingga keselarasan tesis dan kesimpulan paling penting diperiksa."],
    ["Which concluding sentence best demonstrates C2 control in a portfolio essay on urban heat?","Shade is not an amenity but infrastructure, and cities that treat it as optional will pay for the omission.",["In conclusion, urban heat is a big problem, and we should all try to do something about it very soon indeed.","To sum up, in this essay I have talked about shade, trees, and buildings in cities.","Urban heat is a topic that will become more and more important in the future."],"Kesimpulan ini menyintesis argumen menjadi klaim yang tajam dan implikasi yang jelas."],
  ],
};
